FILES = {}

FILES['backend/prisma/schema.prisma'] = '// Schema Prisma - Application de suivi de camps d\'entrainement\n// Par defaut : SQLite (aucune installation requise).\n// Pour passer sur PostgreSQL en production, remplacer le provider ci-dessous\n// par "postgresql" et adapter DATABASE_URL dans .env\n\ngenerator client {\n  provider = "prisma-client-js"\n}\n\ndatasource db {\n  provider = "sqlite"\n  url      = env("DATABASE_URL")\n}\n\n// Note : pas d\'enum Prisma ici (ExerciseUnit / RecurrenceType) car SQLite ne supporte pas\n// les enums natifs. Les valeurs autorisees ("REPS"/"SECONDS", "DAILY"/"WEEKLY"/"EVERY_N_DAYS")\n// sont validees cote API avec zod.\n\nmodel User {\n  id             String   @id @default(cuid())\n  email          String   @unique\n  passwordHash   String\n  name           String\n  weightKg       Float?\n  heightCm       Float?\n  birthDate      DateTime?\n  sex            String?  // "F" | "M" | "AUTRE" | null, libre / optionnel\n  sport          String?  // pratique principale, libre choix dans une liste cote frontend\n  sportLevel     String?  // "LOISIR" | "COMPETITION" | null\n  avatarBase64   String?  // photo de profil encodee en data URL (redimensionnee cote client)\n  location       String?  // ville/region, libre\n  equipment      String?  // JSON array du materiel disponible (voir src/utils/equipment.ts)\n  createdAt      DateTime @default(now())\n\n  memberships    CampMembership[]\n  createdCamps   Camp[]            @relation("CampCreator")\n  createdExos    Exercise[]        @relation("ExerciseCreator")\n  logs           ExerciseLog[]\n  subscriptions  PushSubscription[]\n  badges         UserBadge[]\n  campMessages   CampMessage[]\n  sentMessages   DirectMessage[]   @relation("MessageSender")\n  receivedMessages DirectMessage[] @relation("MessageRecipient")\n  chronoSessions ChronoSession[]\n  circuitLogs    CampCircuitLog[]\n  restDays       RestDay[]\n  favoriteCircuits FavoriteCircuit[]\n  reactions      Reaction[]\n  resetTokens    PasswordResetToken[]\n  sentConnections     Connection[] @relation("ConnectionRequester")\n  receivedConnections Connection[] @relation("ConnectionRecipient")\n}\n\nmodel Exercise {\n  id          String       @id @default(cuid())\n  name        String\n  description String?\n  unit        String       // "REPS" ou "SECONDS"\n  category    String?      // "UPPER" | "LOWER" | "ABS" | "CARDIO" | "FULL_BODY" | "MOBILITY"\n  equipment   String?      // JSON array du materiel necessaire (voir src/utils/equipment.ts) ; vide/null = aucun materiel\n  imageBase64 String?      // photo/illustration de l\'exercice (redimensionnee cote client)\n  videoUrl    String?      // lien video explicatif (ex: YouTube), optionnel\n  isCustom    Boolean      @default(false)\n  createdById String?\n  createdBy   User?        @relation("ExerciseCreator", fields: [createdById], references: [id])\n  createdAt   DateTime     @default(now())\n\n  campExercises CampExercise[]\n  logs          ExerciseLog[]\n}\n\nmodel Camp {\n  id          String    @id @default(cuid())\n  name        String\n  description String?\n  code        String    @unique\n  createdById String\n  createdBy   User      @relation("CampCreator", fields: [createdById], references: [id])\n  startDate   DateTime?\n  endDate     DateTime?\n  createdAt   DateTime  @default(now())\n\n  exercises CampExercise[]\n  circuits  CampCircuit[]\n  members   CampMembership[]\n  logs      ExerciseLog[]\n  circuitLogs CampCircuitLog[]\n  messages  CampMessage[]\n}\n\n// Consigne d\'un exercice au sein d\'un camp : definie UNIQUEMENT par le createur du camp\n// (la "casquette entraineur"). Tous les membres suivent la meme consigne.\nmodel CampExercise {\n  id             String   @id @default(cuid())\n  campId         String\n  exerciseId     String\n  description    String?  // court descriptif/consigne redige par le createur du camp\n  targetSets     Int      @default(3)\n  targetMode     String   @default("FIXED") // "FIXED" (objectif chiffre) ou "MAX" (a fond, sans cible fixe)\n  targetValue    Int?     // nombre de repetitions OU de secondes vise (voir Exercise.unit) ; inutilise si targetMode = MAX\n  recurrenceType String   @default("DAILY") // "DAILY" | "WEEKLY" | "EVERY_N_DAYS" | "WEEKLY_COUNT"\n  daysOfWeek     String?  // JSON array ex: "[1,3,5]" (0=dimanche ... 6=samedi), utilise si WEEKLY\n  intervalDays   Int?     // utilise si EVERY_N_DAYS\n  timesPerWeek   Int?     // utilise si WEEKLY_COUNT (X fois par semaine, n\'importe quel jour)\n  startDate      DateTime @default(now())\n\n  camp     Camp     @relation(fields: [campId], references: [id], onDelete: Cascade)\n  exercise Exercise @relation(fields: [exerciseId], references: [id])\n  logs     ExerciseLog[]\n\n  @@unique([campId, exerciseId])\n}\n\nmodel CampMembership {\n  id       String   @id @default(cuid())\n  userId   String\n  campId   String\n  role     String   @default("PLAYER") // "COACH" (ne fait pas les exercices) | "PLAYER" (participe)\n  joinedAt DateTime @default(now())\n  user     User     @relation(fields: [userId], references: [id], onDelete: Cascade)\n  camp     Camp     @relation(fields: [campId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, campId])\n}\n\nmodel ExerciseLog {\n  id         String   @id @default(cuid())\n  userId     String\n  campId     String\n  exerciseId String\n  date       DateTime // jour concerne (heure normalisee a minuit)\n  setsDone   Int\n  valueDone  Int      // repetitions ou secondes realisees (moyenne/estimation par serie, cf notes)\n  completed  Boolean  @default(true)\n  createdAt  DateTime @default(now())\n\n  user         User          @relation(fields: [userId], references: [id], onDelete: Cascade)\n  camp         Camp          @relation(fields: [campId], references: [id], onDelete: Cascade)\n  exercise     Exercise      @relation(fields: [exerciseId], references: [id])\n  campExercise CampExercise? @relation(fields: [campId, exerciseId], references: [campId, exerciseId])\n\n  @@unique([userId, campId, exerciseId, date])\n}\n\nmodel PushSubscription {\n  id        String   @id @default(cuid())\n  userId    String\n  endpoint  String   @unique\n  p256dh    String\n  auth      String\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\nmodel UserBadge {\n  id        String   @id @default(cuid())\n  userId    String\n  badgeKey  String   // identifiant du badge, voir src/utils/badges.ts pour le catalogue\n  earnedAt  DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, badgeKey])\n}\n\n// Discussion de groupe entre les membres d\'un camp\nmodel CampMessage {\n  id        String   @id @default(cuid())\n  campId    String\n  userId    String\n  body      String\n  createdAt DateTime @default(now())\n\n  camp Camp @relation(fields: [campId], references: [id], onDelete: Cascade)\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\n// Message prive entre deux utilisateurs (reserve aux personnes qui partagent au moins un camp)\nmodel DirectMessage {\n  id          String   @id @default(cuid())\n  senderId    String\n  recipientId String\n  body        String\n  createdAt   DateTime @default(now())\n\n  sender    User @relation("MessageSender", fields: [senderId], references: [id], onDelete: Cascade)\n  recipient User @relation("MessageRecipient", fields: [recipientId], references: [id], onDelete: Cascade)\n}\n\n// Seance de circuit training "libre" (construite depuis l\'onglet Chrono, pas liee a un camp).\n// Enregistree une fois terminee, pour alimenter l\'historique d\'activite de l\'utilisateur.\nmodel ChronoSession {\n  id                   String   @id @default(cuid())\n  userId               String\n  name                 String? // nom optionnel donne par l\'utilisateur\n  items                String  // JSON : liste ordonnee des noms d\'exercices du circuit\n  workSeconds          Int\n  restSeconds          Int\n  rounds               Int\n  roundRestSeconds     Int\n  totalDurationSeconds Int\n  completedAt          DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\n// Circuit training defini par le createur d\'un camp (alternative aux exercices individuels).\n// Compose d\'une liste ordonnee d\'exercices avec temps de travail/repos, nombre de tours, etc.\nmodel CampCircuit {\n  id               String   @id @default(cuid())\n  campId           String\n  name             String\n  description      String?\n  items            String   // JSON : [{ "exerciseId": "...", "name": "..." }, ...] ordonne\n  workSeconds      Int\n  restSeconds      Int\n  rounds           Int\n  roundRestSeconds Int\n  recurrenceType   String   @default("DAILY")\n  daysOfWeek       String?\n  intervalDays     Int?\n  timesPerWeek     Int?\n  startDate        DateTime @default(now())\n\n  camp Camp             @relation(fields: [campId], references: [id], onDelete: Cascade)\n  logs CampCircuitLog[]\n}\n\n// Validation, par un membre, d\'un circuit de camp realise un jour donne\nmodel CampCircuitLog {\n  id              String   @id @default(cuid())\n  userId          String\n  campCircuitId   String\n  campId          String\n  date            DateTime\n  durationSeconds Int\n  completed       Boolean  @default(true)\n  createdAt       DateTime @default(now())\n\n  user        User        @relation(fields: [userId], references: [id], onDelete: Cascade)\n  campCircuit CampCircuit @relation(fields: [campCircuitId], references: [id], onDelete: Cascade)\n  camp        Camp        @relation(fields: [campId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, campCircuitId, date])\n}\n\n// Jour marque comme "repos justifie" par l\'utilisateur (blessure, voyage...) : ce jour\n// n\'est jamais compte comme un manque dans les calculs de regularite/streak, ni comme du\n// depend  (il est neutre). S\'applique globalement, tous camps/exercices confondus.\nmodel RestDay {\n  id        String   @id @default(cuid())\n  userId    String\n  date      DateTime // jour concerne (heure normalisee a minuit)\n  reason    String?\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, date])\n}\n\n// Circuit training "favori" enregistre par un utilisateur depuis l\'onglet Chrono,\n// pour le relancer directement sans le reconstruire.\nmodel FavoriteCircuit {\n  id               String   @id @default(cuid())\n  userId           String\n  name             String\n  items            String   // JSON : liste ordonnee des noms d\'exercices\n  workSeconds      Int\n  restSeconds      Int\n  rounds           Int\n  roundRestSeconds Int\n  createdAt        DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\n// Reaction rapide (encouragement) laissee par un membre de camp sur une seance validee\n// par un autre membre (exercice ou circuit). Purement social, aucun impact sur les stats.\nmodel Reaction {\n  id         String   @id @default(cuid())\n  userId     String   // qui reagit\n  targetType String   // "exercise" ou "circuit" (type de log cible)\n  targetId   String   // id du ExerciseLog ou CampCircuitLog cible\n  type       String   // cle du type de reaction, voir src/utils/reactions.ts\n  createdAt  DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, targetType, targetId, type])\n}\n\n// Jeton de reinitialisation de mot de passe, a duree de vie limitee\nmodel PasswordResetToken {\n  id        String   @id @default(cuid())\n  userId    String\n  token     String   @unique\n  expiresAt DateTime\n  used      Boolean  @default(false)\n  createdAt DateTime @default(now())\n\n  user User @relation(fields: [userId], references: [id], onDelete: Cascade)\n}\n\n// Relation "coequipier" entre deux utilisateurs (demande + acceptation), inspiree d\'une\n// demande d\'ami : donne acces au profil complet (regularite, camps, badges) une fois acceptee.\nmodel Connection {\n  id          String   @id @default(cuid())\n  requesterId String\n  recipientId String\n  status      String   @default("PENDING") // "PENDING" | "ACCEPTED"\n  createdAt   DateTime @default(now())\n\n  requester User @relation("ConnectionRequester", fields: [requesterId], references: [id], onDelete: Cascade)\n  recipient User @relation("ConnectionRecipient", fields: [recipientId], references: [id], onDelete: Cascade)\n\n  @@unique([requesterId, recipientId])\n}\n'
FILES['backend/prisma/seed.ts'] = '// Peuple la base avec un catalogue d\'exercices "de base" a choix large, classes par\n// categorie et materiel necessaire. Lancer avec : npm run seed\nimport { PrismaClient } from "@prisma/client";\n\nconst prisma = new PrismaClient();\n\ntype Category = "UPPER" | "LOWER" | "ABS" | "CARDIO" | "FULL_BODY" | "MOBILITY";\n\ninterface SeedExercise {\n  name: string;\n  description: string;\n  unit: "REPS" | "SECONDS";\n  category: Category;\n  equipment: string[]; // cles du catalogue materiel (voir src/utils/equipment.ts), [] = aucun\n}\n\nconst DEFAULT_EXERCISES: SeedExercise[] = [\n  { name: "Pompes", description: "Pompes classiques, poitrine proche du sol.", unit: "REPS", category: "UPPER", equipment: [] },\n  { name: "Chaise contre le mur", description: "Dos au mur, cuisses a l\'horizontale, on tient.", unit: "SECONDS", category: "LOWER", equipment: [] },\n  { name: "Gainage planche", description: "Gainage ventral sur les avant-bras, corps aligne.", unit: "SECONDS", category: "ABS", equipment: [] },\n  { name: "Gainage laterale (par cote)", description: "Gainage sur un avant-bras, corps de profil.", unit: "SECONDS", category: "ABS", equipment: [] },\n  { name: "Squats", description: "Flexion des jambes, dos droit, cuisses paralleles au sol.", unit: "REPS", category: "LOWER", equipment: [] },\n  { name: "Fentes avant (par jambe)", description: "Fentes alternees, genou arriere proche du sol.", unit: "REPS", category: "LOWER", equipment: [] },\n  { name: "Tractions", description: "Tractions en pronation ou supination a la barre.", unit: "REPS", category: "UPPER", equipment: ["BARRE_TRACTION"] },\n  { name: "Dips", description: "Extension des bras sur barres paralleles ou banc.", unit: "REPS", category: "UPPER", equipment: ["BANC"] },\n  { name: "Abdominaux (crunchs)", description: "Releves de buste, mains aux tempes ou croisees.", unit: "REPS", category: "ABS", equipment: [] },\n  { name: "Mountain climbers", description: "Genoux ramenes alternativement en position de planche.", unit: "REPS", category: "CARDIO", equipment: [] },\n  { name: "Burpees", description: "Squat, planche, pompe, saut : enchainement complet.", unit: "REPS", category: "FULL_BODY", equipment: [] },\n  { name: "Corde a sauter", description: "Sauts a la corde, rythme regulier.", unit: "SECONDS", category: "CARDIO", equipment: ["CORDE_A_SAUTER"] },\n  { name: "Superman (extension dorsale)", description: "Allonge sur le ventre, on souleve bras et jambes.", unit: "SECONDS", category: "ABS", equipment: [] },\n  { name: "Course a pied", description: "Footing ou fractionne, en minutes converties en secondes.", unit: "SECONDS", category: "CARDIO", equipment: [] },\n  { name: "Montee de genoux sur place", description: "Genoux montes alternativement le plus haut possible.", unit: "REPS", category: "CARDIO", equipment: [] },\n  { name: "Developpe couche halteres", description: "Couche sur banc, pousser les halteres au-dessus de la poitrine.", unit: "REPS", category: "UPPER", equipment: ["HALTERES", "BANC"] },\n  { name: "Rowing haltere", description: "Buste incline, tirer l\'haltere vers la hanche.", unit: "REPS", category: "UPPER", equipment: ["HALTERES"] },\n  { name: "Curl biceps", description: "Flexion des coudes, halteres en mains.", unit: "REPS", category: "UPPER", equipment: ["HALTERES"] },\n  { name: "Souleve de terre kettlebell", description: "Charniere de hanche, dos plat, kettlebell au sol.", unit: "REPS", category: "LOWER", equipment: ["KETTLEBELL"] },\n  { name: "Swing kettlebell", description: "Balancer explosif de la kettlebell entre les jambes puis devant soi.", unit: "REPS", category: "FULL_BODY", equipment: ["KETTLEBELL"] },\n  { name: "Elastique tirage horizontal", description: "Tirer l\'elastique vers soi, coudes proches du corps.", unit: "REPS", category: "UPPER", equipment: ["ELASTIQUE"] },\n  { name: "Velo (home trainer)", description: "Pedalage a rythme regulier ou fractionne.", unit: "SECONDS", category: "CARDIO", equipment: ["VELO"] },\n  { name: "Etirements complets", description: "Sequence d\'etirements des principaux groupes musculaires.", unit: "SECONDS", category: "MOBILITY", equipment: ["TAPIS"] },\n  { name: "Mobilite des hanches", description: "Cercles de hanches et ouvertures dynamiques.", unit: "SECONDS", category: "MOBILITY", equipment: [] },\n  { name: "Gainage dynamique (mountain climber lent)", description: "Planche avec genoux qui viennent toucher le coude, rythme controle.", unit: "REPS", category: "ABS", equipment: [] },\n];\n\nasync function main() {\n  for (const exo of DEFAULT_EXERCISES) {\n    const existing = await prisma.exercise.findFirst({ where: { name: exo.name, isCustom: false } });\n    const data = {\n      name: exo.name,\n      description: exo.description,\n      unit: exo.unit,\n      category: exo.category,\n      equipment: JSON.stringify(exo.equipment),\n      isCustom: false,\n    };\n    if (!existing) {\n      await prisma.exercise.create({ data });\n      console.log(`Exercice cree : ${exo.name}`);\n    } else if (!existing.category) {\n      // Complete la categorie/le materiel sur les exercices deja crees avant cette mise a jour\n      await prisma.exercise.update({ where: { id: existing.id }, data: { category: exo.category, equipment: data.equipment } });\n      console.log(`Exercice mis a jour (categorie) : ${exo.name}`);\n    }\n  }\n  console.log("Catalogue d\'exercices pret.");\n}\n\nmain()\n  .catch((e) => {\n    console.error(e);\n    process.exit(1);\n  })\n  .finally(async () => {\n    await prisma.$disconnect();\n  });\n'
FILES['backend/src/utils/badges.ts'] = 'import { prisma } from "../lib/prisma";\nimport { toDayStart, isDueOnDate, computeWeeklyDueDone } from "./recurrence";\n\n// Catalogue des badges disponibles. Purement individuel : aucune comparaison entre utilisateurs.\nexport interface BadgeDefinition {\n  key: string;\n  name: string;\n  description: string;\n  emoji: string;\n}\n\nexport const BADGE_CATALOG: BadgeDefinition[] = [\n  { key: "STREAK_3", name: "3 jours d\'affilee", description: "Une séance réalisée chaque jour, 3 jours de suite.", emoji: "🔥" },\n  { key: "STREAK_7", name: "1 semaine régulière", description: "Une séance réalisée chaque jour, 7 jours de suite.", emoji: "🔥" },\n  { key: "STREAK_30", name: "1 mois de régularité", description: "Une séance réalisée chaque jour, 30 jours de suite.", emoji: "🏅" },\n  { key: "STREAK_100", name: "100 jours de suite", description: "Une séance réalisée chaque jour, 100 jours de suite.", emoji: "🏆" },\n  { key: "TOTAL_10", name: "10 séances", description: "10 séances validees au total.", emoji: "✅" },\n  { key: "TOTAL_50", name: "50 séances", description: "50 séances validees au total.", emoji: "⭐" },\n  { key: "TOTAL_100", name: "100 séances", description: "100 séances validees au total.", emoji: "🌟" },\n  { key: "TOTAL_500", name: "500 séances", description: "500 séances validees au total.", emoji: "💎" },\n  { key: "MERIT_STAR_BRONZE", name: "Étoile du mérite - Bronze", description: "Au moins 60% de tes séances prévues réalisées (sur au moins 2 semaines suivies).", emoji: "🌟" },\n  { key: "MERIT_STAR_SILVER", name: "Étoile du mérite - Argent", description: "Au moins 75% de tes séances prévues réalisées (sur au moins 2 semaines suivies).", emoji: "🌟" },\n  { key: "MERIT_STAR_GOLD", name: "Étoile du mérite - Or", description: "Au moins 90% de tes séances prévues réalisées (sur au moins 2 semaines suivies).", emoji: "🥇" },\n];\n\nconst STREAK_THRESHOLDS: [number, string][] = [\n  [100, "STREAK_100"],\n  [30, "STREAK_30"],\n  [7, "STREAK_7"],\n  [3, "STREAK_3"],\n];\n\nconst TOTAL_THRESHOLDS: [number, string][] = [\n  [500, "TOTAL_500"],\n  [100, "TOTAL_100"],\n  [50, "TOTAL_50"],\n  [10, "TOTAL_10"],\n];\n\nconst MERIT_THRESHOLDS: [number, string][] = [\n  [90, "MERIT_STAR_GOLD"],\n  [75, "MERIT_STAR_SILVER"],\n  [60, "MERIT_STAR_BRONZE"],\n];\nconst MERIT_MIN_DUE_COUNT = 14; // au moins ~2 semaines de recul avant d\'attribuer une etoile\n\n// Calcule le taux de regularite global de l\'utilisateur, tous camps confondus (uniquement\n// les camps ou il participe activement, pas ceux ou il est juste "entraineur"). Renvoie\n// null si pas assez de recul (moins de MERIT_MIN_DUE_COUNT jours/semaines dus).\nexport async function computeOverallRegularityRate(userId: string): Promise<number | null> {\n  const memberships = await prisma.campMembership.findMany({\n    where: { userId, role: { not: "COACH" } },\n    include: { camp: { include: { exercises: true, circuits: true } } },\n  });\n  if (memberships.length === 0) return null;\n\n  const restDays = await prisma.restDay.findMany({ where: { userId }, select: { date: true } });\n  const restDates = new Set(restDays.map((r) => r.date.toISOString().slice(0, 10)));\n  const today = toDayStart(new Date());\n\n  let totalDue = 0;\n  let totalDone = 0;\n\n  for (const membership of memberships) {\n    const { camp } = membership;\n    const joined = toDayStart(membership.joinedAt);\n\n    for (const ce of [...camp.exercises, ...camp.circuits]) {\n      const isCircuit = !("targetSets" in ce);\n      const logs = isCircuit\n        ? await prisma.campCircuitLog.findMany({ where: { userId, campCircuitId: (ce as any).id }, select: { date: true } })\n        : await prisma.exerciseLog.findMany({\n            where: { userId, campId: camp.id, exerciseId: (ce as any).exerciseId },\n            select: { date: true },\n          });\n      const completedDates = new Set(logs.map((l) => l.date.toISOString().slice(0, 10)));\n      const effectiveStart = toDayStart(new Date(Math.max(new Date(ce.startDate).getTime(), joined.getTime())));\n\n      if (ce.recurrenceType === "WEEKLY_COUNT" && ce.timesPerWeek) {\n        const { dueCount, doneCount } = computeWeeklyDueDone(ce.timesPerWeek, effectiveStart, completedDates, today);\n        totalDue += dueCount;\n        totalDone += doneCount;\n      } else {\n        const cursor = new Date(effectiveStart);\n        while (cursor.getTime() <= today.getTime()) {\n          const key = cursor.toISOString().slice(0, 10);\n          if (!restDates.has(key) && isDueOnDate(ce, cursor)) {\n            totalDue++;\n            if (completedDates.has(key)) totalDone++;\n          }\n          cursor.setUTCDate(cursor.getUTCDate() + 1);\n        }\n      }\n    }\n  }\n\n  if (totalDue < MERIT_MIN_DUE_COUNT) return null;\n  return Math.round((totalDone / totalDue) * 100);\n}\n\n// Calcule le plus long "streak" en cours (jours consecutifs avec au moins une séance,\n// tous camps/exercices confondus), en remontant depuis aujourd\'hui ou hier. Les jours\n// marques comme "repos justifie" sont neutres : ils n\'interrompent pas la serie.\nfunction computeGlobalStreak(distinctDates: Set<string>, today: Date, restDates: Set<string> = new Set()): number {\n  const start = toDayStart(today);\n  // Si rien n\'est fait aujourd\'hui, on tolere et on part d\'hier pour ne pas casser la serie\n  // en cours de journee.\n  let cursor = new Date(start);\n  if (!distinctDates.has(cursor.toISOString().slice(0, 10)) && !restDates.has(cursor.toISOString().slice(0, 10))) {\n    cursor.setUTCDate(cursor.getUTCDate() - 1);\n  }\n  let streak = 0;\n  for (let i = 0; i < 3650; i++) {\n    const key = cursor.toISOString().slice(0, 10);\n    if (restDates.has(key)) {\n      cursor.setUTCDate(cursor.getUTCDate() - 1);\n      continue;\n    }\n    if (!distinctDates.has(key)) break;\n    streak++;\n    cursor.setUTCDate(cursor.getUTCDate() - 1);\n  }\n  return streak;\n}\n\n// Recalcule les stats de l\'utilisateur et attribue tout nouveau badge merite.\n// Appele après chaque validation de séance (exercice, circuit de camp, ou séance chrono libre).\n// Idempotent (un badge n\'est jamais attribue deux fois).\nexport async function checkAndAwardBadges(userId: string): Promise<BadgeDefinition[]> {\n  const [exerciseLogs, circuitLogs, chronoSessions] = await Promise.all([\n    prisma.exerciseLog.findMany({ where: { userId }, select: { date: true } }),\n    prisma.campCircuitLog.findMany({ where: { userId }, select: { date: true } }),\n    prisma.chronoSession.findMany({ where: { userId }, select: { completedAt: true } }),\n  ]);\n\n  const distinctDates = new Set<string>([\n    ...exerciseLogs.map((l) => l.date.toISOString().slice(0, 10)),\n    ...circuitLogs.map((l) => l.date.toISOString().slice(0, 10)),\n    ...chronoSessions.map((s) => s.completedAt.toISOString().slice(0, 10)),\n  ]);\n  const totalSessions = exerciseLogs.length + circuitLogs.length + chronoSessions.length;\n  const restDays = await prisma.restDay.findMany({ where: { userId }, select: { date: true } });\n  const restDates = new Set(restDays.map((r) => r.date.toISOString().slice(0, 10)));\n  const streak = computeGlobalStreak(distinctDates, new Date(), restDates);\n\n  const earnedKeys = new Set<string>();\n  // On attribue TOUS les paliers déjà franchis (pas seulement le plus haut), pour garder\n  // l\'historique des badges obtenus même si la serie casse ensuite.\n  for (const [threshold, key] of STREAK_THRESHOLDS) {\n    if (streak >= threshold) earnedKeys.add(key);\n  }\n  for (const [threshold, key] of TOTAL_THRESHOLDS) {\n    if (totalSessions >= threshold) earnedKeys.add(key);\n  }\n\n  const overallRate = await computeOverallRegularityRate(userId);\n  if (overallRate !== null) {\n    for (const [threshold, key] of MERIT_THRESHOLDS) {\n      if (overallRate >= threshold) earnedKeys.add(key);\n    }\n  }\n\n  if (earnedKeys.size === 0) return [];\n\n  const alreadyEarned = await prisma.userBadge.findMany({ where: { userId }, select: { badgeKey: true } });\n  const alreadyEarnedKeys = new Set(alreadyEarned.map((b) => b.badgeKey));\n\n  const newlyEarned = [...earnedKeys].filter((k) => !alreadyEarnedKeys.has(k));\n  if (newlyEarned.length === 0) return [];\n\n  await prisma.userBadge.createMany({\n    data: newlyEarned.map((badgeKey) => ({ userId, badgeKey })),\n  });\n\n  return BADGE_CATALOG.filter((b) => newlyEarned.includes(b.key));\n}\n'
FILES['backend/src/utils/equipment.ts'] = 'export const EQUIPMENT_CATALOG = [\n  { key: "AUCUN", label: "Aucun materiel (poids du corps)" },\n  { key: "HALTERES", label: "Halteres / poids libres" },\n  { key: "BARRE_TRACTION", label: "Barre de traction" },\n  { key: "ELASTIQUE", label: "Elastique de resistance" },\n  { key: "BANC", label: "Banc de musculation" },\n  { key: "KETTLEBELL", label: "Kettlebell" },\n  { key: "CORDE_A_SAUTER", label: "Corde a sauter" },\n  { key: "TAPIS", label: "Tapis de sol" },\n  { key: "VELO", label: "Velo / home trainer" },\n  { key: "AUTRE", label: "Autre materiel specifique" },\n];\n\nexport const EQUIPMENT_KEYS = EQUIPMENT_CATALOG.map((e) => e.key);\n'
FILES['backend/src/routes/exercises.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { EQUIPMENT_KEYS } from "../utils/equipment";\n\nconst router = Router();\nrouter.use(requireAuth);\n\nconst CATEGORY_KEYS = ["UPPER", "LOWER", "ABS", "CARDIO", "FULL_BODY", "MOBILITY"] as const;\n\n// Liste le catalogue complet : exercices par defaut + exercices "maison" ajoutes par les utilisateurs.\n// Filtres optionnels par categorie et/ou materiel disponible (voir query params).\nrouter.get("/", async (req, res) => {\n  const category = req.query.category as string | undefined;\n  const exercises = await prisma.exercise.findMany({ orderBy: [{ isCustom: "asc" }, { name: "asc" }] });\n  const filtered = category ? exercises.filter((e) => e.category === category) : exercises;\n  res.json(filtered);\n});\n\nrouter.get("/categories", (_req, res) => {\n  res.json(CATEGORY_KEYS);\n});\n\n// Répertoire complet du catalogue avec, pour chaque exercice, son nombre d\'utilisations\n// (nombre de camps distincts qui l\'utilisent, tous camps confondus -- même ceux dont\n// l\'utilisateur ne fait pas partie). Purement statistique, aucun detail sur les camps n\'est expose.\nrouter.get("/stats", async (_req, res) => {\n  const exercises = await prisma.exercise.findMany({\n    orderBy: [{ isCustom: "asc" }, { name: "asc" }],\n    include: { _count: { select: { campExercises: true } } },\n  });\n  res.json(\n    exercises.map((e) => ({\n      id: e.id,\n      name: e.name,\n      description: e.description,\n      unit: e.unit,\n      category: e.category,\n      equipment: e.equipment,\n      isCustom: e.isCustom,\n      campCount: e._count.campExercises,\n    }))\n  );\n});\n\nconst createSchema = z.object({\n  name: z.string().min(1, "Le nom de l\'exercice est requis."),\n  description: z.string().optional(),\n  unit: z.enum(["REPS", "SECONDS"]),\n  category: z.enum(CATEGORY_KEYS).optional().nullable(),\n  equipment: z.array(z.enum(EQUIPMENT_KEYS as [string, ...string[]])).optional(),\n  imageBase64: z.string().max(2_000_000).optional().nullable(),\n  videoUrl: z.string().url().max(500).optional().nullable(),\n});\n\n// Permet d\'ajouter un exercice "maison" au catalogue partage, avec categorie, materiel\n// necessaire, et une image/video descriptive optionnelle.\nrouter.post("/", async (req: AuthRequest, res) => {\n  const parsed = createSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n  const { equipment, ...rest } = parsed.data;\n  const exercise = await prisma.exercise.create({\n    data: {\n      ...rest,\n      equipment: equipment ? JSON.stringify(equipment) : null,\n      isCustom: true,\n      createdById: req.userId,\n    },\n  });\n  res.status(201).json(exercise);\n});\n\nconst updateSchema = createSchema.partial();\n\n// Modifie un exercice existant (ex: ajouter une image apres coup) : reserve a son createur\nrouter.put("/:id", async (req: AuthRequest, res) => {\n  const existing = await prisma.exercise.findUnique({ where: { id: req.params.id } });\n  if (!existing) return res.status(404).json({ error: "Exercice introuvable." });\n  if (existing.createdById && existing.createdById !== req.userId) {\n    return res.status(403).json({ error: "Seul le createur de cet exercice peut le modifier." });\n  }\n\n  const parsed = updateSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n  const { equipment, ...rest } = parsed.data;\n\n  const exercise = await prisma.exercise.update({\n    where: { id: req.params.id },\n    data: {\n      ...rest,\n      ...(equipment !== undefined ? { equipment: equipment ? JSON.stringify(equipment) : null } : {}),\n    },\n  });\n  res.json(exercise);\n});\n\nexport default router;\n'
FILES['backend/src/routes/users.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { EQUIPMENT_KEYS } from "../utils/equipment";\nimport { computeOverallRegularityRate } from "../utils/badges";\n\nconst router = Router();\nrouter.use(requireAuth);\n\nconst updateSchema = z.object({\n  name: z.string().min(1).optional(),\n  weightKg: z.number().positive().nullable().optional(),\n  heightCm: z.number().positive().nullable().optional(),\n  birthDate: z.string().nullable().optional(), // format ISO "YYYY-MM-DD"\n  sex: z.enum(["F", "M", "AUTRE"]).nullable().optional(),\n  sport: z.string().max(100).nullable().optional(),\n  sportLevel: z.enum(["LOISIR", "COMPETITION"]).nullable().optional(),\n  location: z.string().max(150).nullable().optional(),\n  equipment: z.array(z.enum(EQUIPMENT_KEYS as [string, ...string[]])).nullable().optional(),\n  // data URL (ex: "data:image/jpeg;base64,...") ; limite large mais raisonnable une fois\n  // l\'image redimensionnee/compressee cote client avant l\'envoi.\n  avatarBase64: z.string().max(2_000_000).nullable().optional(),\n});\n\nrouter.get("/me", async (req: AuthRequest, res) => {\n  const user = await prisma.user.findUnique({ where: { id: req.userId } });\n  if (!user) return res.status(404).json({ error: "Utilisateur introuvable." });\n  const { passwordHash, ...publicUser } = user;\n  res.json(publicUser);\n});\n\nrouter.put("/me", async (req: AuthRequest, res) => {\n  const parsed = updateSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n  const { birthDate, equipment, ...rest } = parsed.data;\n\n  const user = await prisma.user.update({\n    where: { id: req.userId },\n    data: {\n      ...rest,\n      ...(birthDate !== undefined ? { birthDate: birthDate ? new Date(birthDate) : null } : {}),\n      ...(equipment !== undefined ? { equipment: equipment ? JSON.stringify(equipment) : null } : {}),\n    },\n  });\n  const { passwordHash, ...publicUser } = user;\n  res.json(publicUser);\n});\n\n// Resume des camps de l\'utilisateur (nom, descriptif, nombre d\'inscrits, son propre role/\n// participation) + son taux de regularite global, pour la section "Mes camps" du profil.\nrouter.get("/me/summary", async (req: AuthRequest, res) => {\n  const [memberships, overallRegularityRate] = await Promise.all([\n    prisma.campMembership.findMany({\n      where: { userId: req.userId },\n      include: {\n        camp: {\n          include: {\n            exercises: { include: { exercise: true } },\n            _count: { select: { members: true } },\n          },\n        },\n      },\n    }),\n    computeOverallRegularityRate(req.userId!),\n  ]);\n\n  res.json({\n    overallRegularityRate,\n    camps: memberships.map((m) => ({\n      id: m.camp.id,\n      name: m.camp.name,\n      description: m.camp.description,\n      role: m.role,\n      memberCount: m.camp._count.members,\n      exercises: m.camp.exercises.map((ce) => ce.exercise.name),\n    })),\n  });\n});\n\n// Recherche d\'utilisateurs par nom (pour devenir "coequipier"). Ne renvoie que des infos\n// minimales, jamais l\'email ni des donnees sensibles.\nrouter.get("/search", async (req: AuthRequest, res) => {\n  const q = (req.query.q as string | undefined)?.trim();\n  if (!q || q.length < 2) return res.json([]);\n\n  const users = await prisma.user.findMany({\n    where: { name: { contains: q }, id: { not: req.userId } },\n    select: { id: true, name: true, avatarBase64: true, location: true },\n    take: 20,\n  });\n  res.json(users);\n});\n\nexport default router;\n'
FILES['backend/src/routes/connections.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { computeOverallRegularityRate } from "../utils/badges";\nimport { sendPushToUser } from "../services/notifications";\n\nconst router = Router();\nrouter.use(requireAuth);\n\n// Liste mes relations : coequipiers acceptes + demandes en attente (envoyees et recues)\nrouter.get("/", async (req: AuthRequest, res) => {\n  const [sent, received] = await Promise.all([\n    prisma.connection.findMany({\n      where: { requesterId: req.userId },\n      include: { recipient: { select: { id: true, name: true, avatarBase64: true, location: true } } },\n    }),\n    prisma.connection.findMany({\n      where: { recipientId: req.userId },\n      include: { requester: { select: { id: true, name: true, avatarBase64: true, location: true } } },\n    }),\n  ]);\n\n  const accepted = [\n    ...sent.filter((c) => c.status === "ACCEPTED").map((c) => ({ connectionId: c.id, user: c.recipient })),\n    ...received.filter((c) => c.status === "ACCEPTED").map((c) => ({ connectionId: c.id, user: c.requester })),\n  ];\n  const pendingSent = sent\n    .filter((c) => c.status === "PENDING")\n    .map((c) => ({ connectionId: c.id, user: c.recipient }));\n  const pendingReceived = received\n    .filter((c) => c.status === "PENDING")\n    .map((c) => ({ connectionId: c.id, user: c.requester }));\n\n  res.json({ accepted, pendingSent, pendingReceived });\n});\n\nconst requestSchema = z.object({ recipientId: z.string() });\n\n// Envoie une demande pour devenir "coequipier" d\'un autre utilisateur\nrouter.post("/", async (req: AuthRequest, res) => {\n  const parsed = requestSchema.safeParse(req.body);\n  if (!parsed.success) return res.status(400).json({ error: "Requete invalide." });\n  const { recipientId } = parsed.data;\n\n  if (recipientId === req.userId) {\n    return res.status(400).json({ error: "Impossible de s\'ajouter soi-meme." });\n  }\n\n  const existing = await prisma.connection.findFirst({\n    where: {\n      OR: [\n        { requesterId: req.userId!, recipientId },\n        { requesterId: recipientId, recipientId: req.userId! },\n      ],\n    },\n  });\n  if (existing) {\n    return res.status(409).json({ error: "Une demande existe deja avec cette personne." });\n  }\n\n  const connection = await prisma.connection.create({\n    data: { requesterId: req.userId!, recipientId, status: "PENDING" },\n  });\n\n  const me = await prisma.user.findUnique({ where: { id: req.userId } });\n  sendPushToUser(recipientId, "🤝 Nouvelle demande", `${me?.name ?? "Quelqu\'un"} veut devenir ton coequipier.`).catch(\n    () => {}\n  );\n\n  res.status(201).json(connection);\n});\n\n// Accepte une demande recue\nrouter.post("/:id/accept", async (req: AuthRequest, res) => {\n  const connection = await prisma.connection.findUnique({ where: { id: req.params.id } });\n  if (!connection || connection.recipientId !== req.userId) {\n    return res.status(404).json({ error: "Demande introuvable." });\n  }\n  const updated = await prisma.connection.update({ where: { id: req.params.id }, data: { status: "ACCEPTED" } });\n  res.json(updated);\n});\n\n// Refuse une demande recue, ou annule/supprime une relation existante\nrouter.delete("/:id", async (req: AuthRequest, res) => {\n  const connection = await prisma.connection.findUnique({ where: { id: req.params.id } });\n  if (!connection || (connection.recipientId !== req.userId && connection.requesterId !== req.userId)) {\n    return res.status(404).json({ error: "Relation introuvable." });\n  }\n  await prisma.connection.delete({ where: { id: req.params.id } });\n  res.status(204).send();\n});\n\nasync function areTeammatesOrCampmates(userId: string, otherUserId: string): Promise<boolean> {\n  const connection = await prisma.connection.findFirst({\n    where: {\n      status: "ACCEPTED",\n      OR: [\n        { requesterId: userId, recipientId: otherUserId },\n        { requesterId: otherUserId, recipientId: userId },\n      ],\n    },\n  });\n  if (connection) return true;\n\n  const sharedCamp = await prisma.campMembership.findFirst({\n    where: { userId: otherUserId, camp: { members: { some: { userId } } } },\n  });\n  return !!sharedCamp;\n}\n\n// Profil public d\'un coequipier (ou d\'un membre d\'un camp commun) : infos de base +\n// taux de regularite global + liste de ses camps.\nrouter.get("/:userId/profile", async (req: AuthRequest, res) => {\n  const otherUserId = req.params.userId;\n  if (!(await areTeammatesOrCampmates(req.userId!, otherUserId))) {\n    return res.status(403).json({ error: "Vous devez etre coequipiers ou partager un camp pour voir ce profil." });\n  }\n\n  const user = await prisma.user.findUnique({\n    where: { id: otherUserId },\n    select: {\n      id: true,\n      name: true,\n      avatarBase64: true,\n      location: true,\n      sport: true,\n      sportLevel: true,\n      createdAt: true,\n    },\n  });\n  if (!user) return res.status(404).json({ error: "Utilisateur introuvable." });\n\n  const [overallRegularityRate, memberships, badgeCount] = await Promise.all([\n    computeOverallRegularityRate(otherUserId),\n    prisma.campMembership.findMany({\n      where: { userId: otherUserId },\n      include: { camp: { include: { _count: { select: { members: true } } } } },\n    }),\n    prisma.userBadge.count({ where: { userId: otherUserId } }),\n  ]);\n\n  res.json({\n    ...user,\n    overallRegularityRate,\n    badgeCount,\n    camps: memberships.map((m) => ({\n      id: m.camp.id,\n      name: m.camp.name,\n      description: m.camp.description,\n      memberCount: m.camp._count.members,\n    })),\n  });\n});\n\nexport default router;\n'
FILES['backend/src/routes/camps.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { generateCampCode } from "../utils/code";\nimport { isDueOnDate, toDayStart, computeWeeklyDueDone } from "../utils/recurrence";\n\nconst router = Router();\nrouter.use(requireAuth);\n\nconst createCampSchema = z.object({\n  name: z.string().min(1, "Le nom du camp est requis."),\n  description: z.string().max(500).optional().nullable(),\n  exerciseIds: z.array(z.string()).min(1, "Selectionne au moins un exercice."),\n  startDate: z.string().optional().nullable(), // format ISO "YYYY-MM-DD"\n  endDate: z.string().optional().nullable(),\n  creatorRole: z.enum(["COACH", "PLAYER"]).optional(), // "COACH" = ne fait pas les exercices lui-meme\n});\n\n// Créé un camp : choix d\'un ensemble d\'exercices, generation d\'un code d\'invitation.\n// Le créateur devient automatiquement membre du camp, avec le role qu\'il choisit\n// ("entraineur" = ne fait pas les exercices, "coequipier" = les fait aussi).\nrouter.post("/", async (req: AuthRequest, res) => {\n  const parsed = createCampSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n  const { name, description, exerciseIds, startDate, endDate, creatorRole } = parsed.data;\n\n  if (startDate && endDate && new Date(endDate) < new Date(startDate)) {\n    return res.status(400).json({ error: "La date de fin doit être après la date de debut." });\n  }\n\n  // On généré un code unique (très faible probabilite de collision, on retente si besoin)\n  let code = generateCampCode();\n  for (let attempt = 0; attempt < 5; attempt++) {\n    const clash = await prisma.camp.findUnique({ where: { code } });\n    if (!clash) break;\n    code = generateCampCode();\n  }\n\n  const camp = await prisma.camp.create({\n    data: {\n      name,\n      description: description || null,\n      code,\n      createdById: req.userId!,\n      startDate: startDate ? new Date(startDate) : null,\n      endDate: endDate ? new Date(endDate) : null,\n      exercises: { create: exerciseIds.map((exerciseId) => ({ exerciseId })) },\n      members: { create: [{ userId: req.userId!, role: creatorRole === "COACH" ? "COACH" : "PLAYER" }] },\n    },\n    include: { exercises: { include: { exercise: true } }, members: true },\n  });\n\n  res.status(201).json(camp);\n});\n\nconst joinSchema = z.object({ code: z.string().min(1) });\n\n// Apercu d\'un camp par son code, SANS le rejoindre : permet de verifier le materiel\n// necessaire avant de s\'inscrire (le materiel manquant n\'empeche pas de forcer l\'inscription).\nrouter.get("/preview", async (req: AuthRequest, res) => {\n  const code = ((req.query.code as string) || "").trim().toUpperCase();\n  if (!code) return res.status(400).json({ error: "Code requis." });\n\n  const camp = await prisma.camp.findUnique({\n    where: { code },\n    include: { exercises: { include: { exercise: true } }, _count: { select: { members: true } } },\n  });\n  if (!camp) return res.status(404).json({ error: "Aucun camp ne correspond a ce code." });\n\n  const requiredEquipment = [\n    ...new Set(\n      camp.exercises.flatMap((ce) => (ce.exercise.equipment ? (JSON.parse(ce.exercise.equipment) as string[]) : []))\n    ),\n  ];\n\n  res.json({\n    id: camp.id,\n    name: camp.name,\n    description: camp.description,\n    memberCount: camp._count.members,\n    exerciseNames: camp.exercises.map((ce) => ce.exercise.name),\n    requiredEquipment,\n  });\n});\n\n// Rejoint un camp existant via son code d\'invitation\nrouter.post("/join", async (req: AuthRequest, res) => {\n  const parsed = joinSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: "Code requis." });\n  }\n  const code = parsed.data.code.trim().toUpperCase();\n\n  const camp = await prisma.camp.findUnique({ where: { code } });\n  if (!camp) {\n    return res.status(404).json({ error: "Aucun camp ne correspond a ce code." });\n  }\n\n  const existing = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId: req.userId!, campId: camp.id } },\n  });\n  if (existing) {\n    return res.status(200).json({ message: "Tu es déjà membre de ce camp.", campId: camp.id });\n  }\n\n  await prisma.campMembership.create({ data: { userId: req.userId!, campId: camp.id } });\n  res.status(201).json({ message: `Bienvenue dans le camp "${camp.name}" !`, campId: camp.id });\n});\n\n// Liste les camps dont l\'utilisateur est membre\nrouter.get("/mine", async (req: AuthRequest, res) => {\n  const memberships = await prisma.campMembership.findMany({\n    where: { userId: req.userId },\n    include: {\n      camp: {\n        include: {\n          exercises: { include: { exercise: true } },\n          _count: { select: { members: true } },\n        },\n      },\n    },\n    orderBy: { joinedAt: "desc" },\n  });\n  const today = toDayStart(new Date());\n  res.json(\n    memberships.map((m) => ({\n      ...m.camp,\n      isEnded: !!(m.camp.endDate && today.getTime() > toDayStart(m.camp.endDate).getTime()),\n      myRole: m.role,\n    }))\n  );\n});\n\n// Detail d\'un camp (vérifie que l\'utilisateur en est bien membre)\nrouter.get("/:id", async (req: AuthRequest, res) => {\n  const membership = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId: req.userId!, campId: req.params.id } },\n  });\n  if (!membership) {\n    return res.status(403).json({ error: "Tu n\'es pas membre de ce camp." });\n  }\n\n  const camp = await prisma.camp.findUnique({\n    where: { id: req.params.id },\n    include: {\n      exercises: { include: { exercise: true } },\n      circuits: true,\n      members: { include: { user: { select: { id: true, name: true } } } },\n    },\n  });\n  if (!camp) return res.status(404).json({ error: "Camp introuvable." });\n\n  const isEnded = !!(camp.endDate && toDayStart(new Date()).getTime() > toDayStart(camp.endDate).getTime());\n  res.json({ ...camp, isEnded, myRole: membership.role });\n});\n\nconst updateCampSchema = z.object({\n  name: z.string().min(1).optional(),\n  description: z.string().max(500).optional().nullable(),\n});\n\n// Modifie le nom/descriptif d\'un camp : réservé au créateur du camp\nrouter.put("/:id", async (req: AuthRequest, res) => {\n  const camp = await prisma.camp.findUnique({ where: { id: req.params.id } });\n  if (!camp) return res.status(404).json({ error: "Camp introuvable." });\n  if (camp.createdById !== req.userId) {\n    return res.status(403).json({ error: "Seul le créateur du camp peut le modifier." });\n  }\n\n  const parsed = updateCampSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n\n  const updated = await prisma.camp.update({\n    where: { id: req.params.id },\n    data: parsed.data,\n  });\n  res.json(updated);\n});\n\n// Supprime definitivement un camp : réservé au créateur du camp.\n// Supprime aussi en cascade les exercices du camp, les adhesions, les logs et les messages associes.\nrouter.delete("/:id", async (req: AuthRequest, res) => {\n  const camp = await prisma.camp.findUnique({ where: { id: req.params.id } });\n  if (!camp) return res.status(404).json({ error: "Camp introuvable." });\n  if (camp.createdById !== req.userId) {\n    return res.status(403).json({ error: "Seul le créateur du camp peut le supprimer." });\n  }\n\n  await prisma.camp.delete({ where: { id: req.params.id } });\n  res.status(204).send();\n});\n\n// Classement des membres du camp base UNIQUEMENT sur leur régularité personnelle\n// (taux de séances réalisées par rapport aux séances dues, et jours consecutifs) --\n// jamais sur les performances (poids, répétitions, etc.).\nrouter.get("/:id/leaderboard", async (req: AuthRequest, res) => {\n  const campId = req.params.id;\n  const membership = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId: req.userId!, campId } },\n  });\n  if (!membership) return res.status(403).json({ error: "Tu n\'es pas membre de ce camp." });\n\n  const camp = await prisma.camp.findUnique({\n    where: { id: campId },\n    include: {\n      exercises: true,\n      members: { include: { user: { select: { id: true, name: true } } } },\n    },\n  });\n  if (!camp) return res.status(404).json({ error: "Camp introuvable." });\n\n  const today = toDayStart(new Date());\n  const results = [];\n\n  for (const member of camp.members) {\n    if (member.role === "COACH") continue; // n\'a pas d\'obligation de pratique, pas classe\n\n    const logs = await prisma.exerciseLog.findMany({\n      where: { userId: member.userId, campId },\n      select: { date: true },\n    });\n    const completedDates = new Set(logs.map((l) => l.date.toISOString().slice(0, 10)));\n    const restDays = await prisma.restDay.findMany({ where: { userId: member.userId }, select: { date: true } });\n    const restDates = new Set(restDays.map((r) => r.date.toISOString().slice(0, 10)));\n\n    let dueCount = 0;\n    let doneCount = 0;\n    for (const ce of camp.exercises) {\n      const effectiveStart = toDayStart(\n        new Date(Math.max(new Date(ce.startDate).getTime(), new Date(member.joinedAt).getTime()))\n      );\n\n      if (ce.recurrenceType === "WEEKLY_COUNT" && ce.timesPerWeek) {\n        const weekly = computeWeeklyDueDone(ce.timesPerWeek, effectiveStart, completedDates, today);\n        dueCount += weekly.dueCount;\n        doneCount += weekly.doneCount;\n        continue;\n      }\n\n      const cursor = new Date(effectiveStart);\n      while (cursor.getTime() <= today.getTime()) {\n        const key = cursor.toISOString().slice(0, 10);\n        if (!restDates.has(key) && isDueOnDate(ce, cursor)) {\n          dueCount++;\n          if (completedDates.has(key)) doneCount++;\n        }\n        cursor.setUTCDate(cursor.getUTCDate() + 1);\n      }\n    }\n    const regularityRate = dueCount > 0 ? Math.round((doneCount / dueCount) * 100) : 0;\n\n    // Streak propre a ce camp : jours consecutifs (en remontant depuis aujourd\'hui/hier)\n    // avec au moins une séance validee dans ce camp. Les jours de repos justifie sont neutres.\n    let streak = 0;\n    const cursor2 = toDayStart(today);\n    if (!completedDates.has(cursor2.toISOString().slice(0, 10)) && !restDates.has(cursor2.toISOString().slice(0, 10))) {\n      cursor2.setUTCDate(cursor2.getUTCDate() - 1);\n    }\n    for (let i = 0; i < 3650; i++) {\n      const key = cursor2.toISOString().slice(0, 10);\n      if (restDates.has(key)) {\n        cursor2.setUTCDate(cursor2.getUTCDate() - 1);\n        continue;\n      }\n      if (!completedDates.has(key)) break;\n      streak++;\n      cursor2.setUTCDate(cursor2.getUTCDate() - 1);\n    }\n\n    results.push({\n      userId: member.userId,\n      name: member.user.name,\n      regularityRate,\n      streak,\n      dueCount,\n      doneCount,\n    });\n  }\n\n  results.sort((a, b) => b.regularityRate - a.regularityRate || b.streak - a.streak);\n  res.json(results);\n});\n\n// Duplique un camp (nom, descriptif, exercices et circuits avec leurs consignes) pour\n// relancer une nouvelle "saison" sans tout reconfigurer. Réservé au créateur du camp.\n// Les membres, l\'historique et les messages ne sont PAS copies.\nrouter.post("/:id/duplicate", async (req: AuthRequest, res) => {\n  const original = await prisma.camp.findUnique({\n    where: { id: req.params.id },\n    include: { exercises: true, circuits: true },\n  });\n  if (!original) return res.status(404).json({ error: "Camp introuvable." });\n  if (original.createdById !== req.userId) {\n    return res.status(403).json({ error: "Seul le créateur du camp peut le dupliquer." });\n  }\n\n  let code = generateCampCode();\n  for (let attempt = 0; attempt < 5; attempt++) {\n    const clash = await prisma.camp.findUnique({ where: { code } });\n    if (!clash) break;\n    code = generateCampCode();\n  }\n\n  const duplicate = await prisma.camp.create({\n    data: {\n      name: `${original.name} (copie)`,\n      description: original.description,\n      code,\n      createdById: req.userId!,\n      exercises: {\n        create: original.exercises.map((ce) => ({\n          exerciseId: ce.exerciseId,\n          description: ce.description,\n          targetSets: ce.targetSets,\n          targetMode: ce.targetMode,\n          targetValue: ce.targetValue,\n          recurrenceType: ce.recurrenceType,\n          daysOfWeek: ce.daysOfWeek,\n          intervalDays: ce.intervalDays,\n        })),\n      },\n      circuits: {\n        create: original.circuits.map((c) => ({\n          name: c.name,\n          description: c.description,\n          items: c.items,\n          workSeconds: c.workSeconds,\n          restSeconds: c.restSeconds,\n          rounds: c.rounds,\n          roundRestSeconds: c.roundRestSeconds,\n          recurrenceType: c.recurrenceType,\n          daysOfWeek: c.daysOfWeek,\n          intervalDays: c.intervalDays,\n        })),\n      },\n      members: { create: [{ userId: req.userId! }] },\n    },\n  });\n\n  res.status(201).json(duplicate);\n});\n\n// Vue calendrier d\'un mois pour l\'utilisateur courant : pour chaque jour, etait-ce du\n// (au moins un exercice/circuit du camp) et a-t-il ete fait (au moins un valide) ?\nrouter.get("/:id/calendar", async (req: AuthRequest, res) => {\n  const campId = req.params.id;\n  const membership = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId: req.userId!, campId } },\n  });\n  if (!membership) return res.status(403).json({ error: "Tu n\'es pas membre de ce camp." });\n\n  const monthParam = (req.query.month as string) || new Date().toISOString().slice(0, 7); // "YYYY-MM"\n  const [yearStr, monthStr] = monthParam.split("-");\n  const year = Number(yearStr);\n  const month = Number(monthStr); // 1-12\n\n  const camp = await prisma.camp.findUnique({\n    where: { id: campId },\n    include: { exercises: true, circuits: true },\n  });\n  if (!camp) return res.status(404).json({ error: "Camp introuvable." });\n\n  const [logs, circuitLogs, restDays] = await Promise.all([\n    prisma.exerciseLog.findMany({ where: { userId: req.userId, campId }, select: { date: true } }),\n    prisma.campCircuitLog.findMany({ where: { userId: req.userId, campId }, select: { date: true } }),\n    prisma.restDay.findMany({ where: { userId: req.userId }, select: { date: true } }),\n  ]);\n  const doneDates = new Set([\n    ...logs.map((l) => l.date.toISOString().slice(0, 10)),\n    ...circuitLogs.map((l) => l.date.toISOString().slice(0, 10)),\n  ]);\n  const restDates = new Set(restDays.map((r) => r.date.toISOString().slice(0, 10)));\n\n  const daysInMonth = new Date(Date.UTC(year, month, 0)).getUTCDate();\n  const days = [];\n  for (let d = 1; d <= daysInMonth; d++) {\n    const date = new Date(Date.UTC(year, month - 1, d));\n    const key = date.toISOString().slice(0, 10);\n    const due =\n      (camp.startDate ? date.getTime() >= toDayStart(camp.startDate).getTime() : true) &&\n      (camp.endDate ? date.getTime() <= toDayStart(camp.endDate).getTime() : true) &&\n      (camp.exercises.some((ce) => isDueOnDate(ce, date)) || camp.circuits.some((c) => isDueOnDate(c, date)));\n    days.push({\n      date: key,\n      due,\n      done: doneDates.has(key),\n      rest: restDates.has(key),\n    });\n  }\n\n  res.json({ month: monthParam, days });\n});\n\n// Fil d\'activité du camp : dernières séances validees par tous les membres (avec reactions),\n// pour s\'encourager sans se comparer sur la performance.\nrouter.get("/:id/feed", async (req: AuthRequest, res) => {\n  const campId = req.params.id;\n  const membership = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId: req.userId!, campId } },\n  });\n  if (!membership) return res.status(403).json({ error: "Tu n\'es pas membre de ce camp." });\n\n  const [logs, circuitLogs] = await Promise.all([\n    prisma.exerciseLog.findMany({\n      where: { campId },\n      include: { user: { select: { id: true, name: true } }, exercise: { select: { name: true, unit: true } } },\n      orderBy: { createdAt: "desc" },\n      take: 30,\n    }),\n    prisma.campCircuitLog.findMany({\n      where: { campId },\n      include: { user: { select: { id: true, name: true } }, campCircuit: { select: { name: true } } },\n      orderBy: { createdAt: "desc" },\n      take: 30,\n    }),\n  ]);\n\n  const feedItemsRaw = [\n    ...logs.map((l) => ({\n      targetType: "exercise" as const,\n      targetId: l.id,\n      userId: l.user.id,\n      userName: l.user.name,\n      label: l.exercise.name,\n      date: l.date.toISOString(),\n      createdAt: l.createdAt,\n      setsDone: l.setsDone as number | null,\n      valueDone: l.valueDone as number | null,\n      unit: l.exercise.unit as string | null,\n      durationSeconds: null as number | null,\n    })),\n    ...circuitLogs.map((l) => ({\n      targetType: "circuit" as const,\n      targetId: l.id,\n      userId: l.user.id,\n      userName: l.user.name,\n      label: l.campCircuit.name,\n      date: l.date.toISOString(),\n      createdAt: l.createdAt,\n      setsDone: null as number | null,\n      valueDone: null as number | null,\n      unit: null as string | null,\n      durationSeconds: l.durationSeconds as number | null,\n    })),\n  ]\n    .sort((a, b) => b.createdAt.getTime() - a.createdAt.getTime())\n    .slice(0, 30);\n\n  const reactions = await prisma.reaction.findMany({\n    where: {\n      OR: feedItemsRaw.map((i) => ({ targetType: i.targetType, targetId: i.targetId })),\n    },\n  });\n\n  const feedItems = feedItemsRaw.map((item) => {\n    const itemReactions = reactions.filter((r) => r.targetType === item.targetType && r.targetId === item.targetId);\n    const byType = new Map<string, { count: number; reactedByMe: boolean }>();\n    for (const r of itemReactions) {\n      const entry = byType.get(r.type) ?? { count: 0, reactedByMe: false };\n      entry.count++;\n      if (r.userId === req.userId) entry.reactedByMe = true;\n      byType.set(r.type, entry);\n    }\n    return {\n      ...item,\n      reactions: [...byType.entries()].map(([type, v]) => ({ type, ...v })),\n    };\n  });\n\n  res.json(feedItems);\n});\n\nexport default router;\n'
FILES['backend/src/routes/today.ts'] = 'import { Router } from "express";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { isDueOnDate, toDayStart, weekStart } from "../utils/recurrence";\n\nconst router = Router();\nrouter.use(requireAuth);\n\n// Renvoie, pour aujourd\'hui, tous les exercices et circuits dus (tous camps dont l\'utilisateur\n// est membre) selon la consigne définie par le créateur de chaque camp, avec l\'info si déjà fait.\nrouter.get("/", async (req: AuthRequest, res) => {\n  const today = toDayStart(new Date());\n  const weekStartDate = weekStart(today);\n\n  const memberships = await prisma.campMembership.findMany({\n    where: { userId: req.userId },\n    include: {\n      camp: {\n        include: { exercises: { include: { exercise: true } }, circuits: true },\n      },\n    },\n  });\n\n  const campExercises = memberships\n    .filter((m) => m.role !== "COACH")\n    .flatMap((m) => m.camp.exercises.map((ce) => ({ ...ce, camp: m.camp })));\n  const campCircuits = memberships\n    .filter((m) => m.role !== "COACH")\n    .flatMap((m) => m.camp.circuits.map((cc) => ({ ...cc, camp: m.camp })));\n\n  // On ne propose que ce dont le camp est en cours (entre sa date de début et de fin, si définies)\n  function withinCampDates(camp: { startDate: Date | null; endDate: Date | null }) {\n    if (camp.startDate && today.getTime() < toDayStart(camp.startDate).getTime()) return false;\n    if (camp.endDate && today.getTime() > toDayStart(camp.endDate).getTime()) return false;\n    return true;\n  }\n\n  const candidateExercises = campExercises.filter((ce) => withinCampDates(ce.camp) && isDueOnDate(ce, today));\n  const candidateCircuits = campCircuits.filter((cc) => withinCampDates(cc.camp) && isDueOnDate(cc, today));\n\n  const [logsToday, circuitLogsToday] = await Promise.all([\n    prisma.exerciseLog.findMany({ where: { userId: req.userId, date: today } }),\n    prisma.campCircuitLog.findMany({ where: { userId: req.userId, date: today } }),\n  ]);\n  const logByExercise = new Map(logsToday.map((l) => [`${l.campId}:${l.exerciseId}`, l]));\n  const logByCircuit = new Map(circuitLogsToday.map((l) => [l.campCircuitId, l]));\n\n  // Pour les consignes "X fois par semaine, n\'importe quel jour" (WEEKLY_COUNT), on masque\n  // l\'element si le quota de la semaine est déjà atteint par un autre jour (pas besoin de\n  // rappeler quelque chose déjà fait cette semaine), sauf si aujourd\'hui est déjà valide.\n  async function weeklyCountSatisfied(\n    kind: "exercise" | "circuit",\n    campId: string,\n    targetId: string,\n    timesPerWeek: number | null\n  ): Promise<boolean> {\n    if (!timesPerWeek) return false;\n    const weekLogs =\n      kind === "exercise"\n        ? await prisma.exerciseLog.count({\n            where: { userId: req.userId, campId, exerciseId: targetId, date: { gte: weekStartDate, lte: today } },\n          })\n        : await prisma.campCircuitLog.count({\n            where: { userId: req.userId, campId, campCircuitId: targetId, date: { gte: weekStartDate, lte: today } },\n          });\n    return weekLogs >= timesPerWeek;\n  }\n\n  const dueExercises = [];\n  for (const ce of candidateExercises) {\n    if (ce.recurrenceType === "WEEKLY_COUNT") {\n      const doneTodayAlready = logByExercise.has(`${ce.campId}:${ce.exerciseId}`);\n      const satisfied = await weeklyCountSatisfied("exercise", ce.campId, ce.exerciseId, ce.timesPerWeek);\n      if (satisfied && !doneTodayAlready) continue; // quota déjà atteint cette semaine, on masque\n    }\n    dueExercises.push(ce);\n  }\n\n  const dueCircuits = [];\n  for (const cc of candidateCircuits) {\n    if (cc.recurrenceType === "WEEKLY_COUNT") {\n      const doneTodayAlready = logByCircuit.has(cc.id);\n      const satisfied = await weeklyCountSatisfied("circuit", cc.campId, cc.id, cc.timesPerWeek);\n      if (satisfied && !doneTodayAlready) continue;\n    }\n    dueCircuits.push(cc);\n  }\n\n  // Pour les exercices en mode "MAX", on va chercher le record personnel précédent à titre de référence\n  const maxExercises = dueExercises.filter((ce) => ce.targetMode === "MAX");\n  const bestByExercise = new Map<string, number>();\n  for (const ce of maxExercises) {\n    const best = await prisma.exerciseLog.findFirst({\n      where: { userId: req.userId, campId: ce.campId, exerciseId: ce.exerciseId },\n      orderBy: { valueDone: "desc" },\n    });\n    if (best) bestByExercise.set(`${ce.campId}:${ce.exerciseId}`, best.valueDone);\n  }\n\n  const exerciseItems = dueExercises.map((ce) => {\n    const key = `${ce.campId}:${ce.exerciseId}`;\n    const log = logByExercise.get(key);\n    return {\n      kind: "exercise" as const,\n      campExerciseId: ce.id,\n      campId: ce.campId,\n      campName: ce.camp.name,\n      exerciseId: ce.exerciseId,\n      exerciseName: ce.exercise.name,\n      description: ce.description,\n      unit: ce.exercise.unit,\n      imageBase64: ce.exercise.imageBase64,\n      videoUrl: ce.exercise.videoUrl,\n      targetSets: ce.targetSets,\n      targetMode: ce.targetMode,\n      targetValue: ce.targetValue,\n      personalBest: bestByExercise.get(key) ?? null,\n      done: !!log,\n      log: log ? { setsDone: log.setsDone, valueDone: log.valueDone } : null,\n    };\n  });\n\n  const circuitItems = dueCircuits.map((cc) => {\n    const log = logByCircuit.get(cc.id);\n    return {\n      kind: "circuit" as const,\n      campCircuitId: cc.id,\n      campId: cc.campId,\n      campName: cc.camp.name,\n      name: cc.name,\n      description: cc.description,\n      items: JSON.parse(cc.items) as { exerciseId?: string; name: string }[],\n      workSeconds: cc.workSeconds,\n      restSeconds: cc.restSeconds,\n      rounds: cc.rounds,\n      roundRestSeconds: cc.roundRestSeconds,\n      done: !!log,\n    };\n  });\n\n  res.json({ date: today.toISOString().slice(0, 10), items: exerciseItems, circuits: circuitItems });\n});\n\nexport default router;\n'
FILES['backend/src/routes/reactions.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { REACTION_CATALOG, REACTION_KEYS } from "../utils/reactions";\nimport { sendPushToUser } from "../services/notifications";\n\nconst router = Router();\nrouter.use(requireAuth);\n\nrouter.get("/catalog", (_req, res) => {\n  res.json(REACTION_CATALOG);\n});\n\nconst toggleSchema = z.object({\n  targetType: z.enum(["exercise", "circuit"]),\n  targetId: z.string(),\n  type: z.enum(REACTION_KEYS as [string, ...string[]]),\n});\n\n// Ajoute ou retire une reaction (bascule) sur une séance validee par un membre du même camp.\nrouter.post("/", async (req: AuthRequest, res) => {\n  const parsed = toggleSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: "Reaction invalide." });\n  }\n  const { targetType, targetId, type } = parsed.data;\n\n  // Vérifie que la cible existe et recupere son camp, pour s\'assurer que l\'utilisateur\n  // en est bien membre (on ne peut reagir qu\'aux séances de ses propres camps).\n  let campId: string | null = null;\n  let ownerId: string | null = null;\n  if (targetType === "exercise") {\n    const log = await prisma.exerciseLog.findUnique({ where: { id: targetId } });\n    campId = log?.campId ?? null;\n    ownerId = log?.userId ?? null;\n  } else {\n    const log = await prisma.campCircuitLog.findUnique({ where: { id: targetId } });\n    campId = log?.campId ?? null;\n    ownerId = log?.userId ?? null;\n  }\n  if (!campId) return res.status(404).json({ error: "Séance introuvable." });\n\n  const membership = await prisma.campMembership.findUnique({\n    where: { userId_campId: { userId: req.userId!, campId } },\n  });\n  if (!membership) return res.status(403).json({ error: "Tu n\'es pas membre de ce camp." });\n\n  const existing = await prisma.reaction.findUnique({\n    where: { userId_targetType_targetId_type: { userId: req.userId!, targetType, targetId, type } },\n  });\n\n  if (existing) {\n    await prisma.reaction.delete({ where: { id: existing.id } });\n    return res.json({ active: false });\n  }\n\n  await prisma.reaction.create({ data: { userId: req.userId!, targetType, targetId, type } });\n\n  if (ownerId && ownerId !== req.userId) {\n    const def = REACTION_CATALOG.find((r) => r.key === type);\n    const me = await prisma.user.findUnique({ where: { id: req.userId } });\n    sendPushToUser(\n      ownerId,\n      `${def?.emoji ?? "👏"} Nouvelle reaction`,\n      `${me?.name ?? "Quelqu\'un"} a reagi a ta séance (${def?.label ?? type}).`\n    ).catch(() => {});\n  }\n\n  res.status(201).json({ active: true });\n});\n\nexport default router;\n'
FILES['backend/src/routes/logs.ts'] = 'import { Router } from "express";\nimport { z } from "zod";\nimport { prisma } from "../lib/prisma";\nimport { AuthRequest, requireAuth } from "../middleware/auth";\nimport { toDayStart } from "../utils/recurrence";\nimport { checkAndAwardBadges } from "../utils/badges";\n\nconst router = Router();\nrouter.use(requireAuth);\n\nconst logSchema = z.object({\n  campId: z.string().optional(),\n  campIds: z.array(z.string()).optional(), // pour valider un meme exercice sur plusieurs camps a la fois\n  exerciseId: z.string(),\n  setsDone: z.number().min(1),\n  valueDone: z.number().min(0),\n  date: z.string().optional(), // optionnel, permet de rattraper un jour passe ; defaut = aujourd\'hui\n});\n\n// Enregistre (ou met à jour) la réalisation d\'un exercice pour une journée donnée, pour un\n// ou plusieurs camps a la fois (utile quand le meme exercice est present dans plusieurs camps\n// et que l\'utilisateur souhaite que ca compte pour tous en une seule validation).\n// L\'idee n\'est pas la performance, mais la régularité : un log = "je l\'ai fait aujourd\'hui".\nrouter.post("/", async (req: AuthRequest, res) => {\n  const parsed = logSchema.safeParse(req.body);\n  if (!parsed.success) {\n    return res.status(400).json({ error: parsed.error.issues[0].message });\n  }\n  const { campId, campIds, exerciseId, setsDone, valueDone, date } = parsed.data;\n\n  const targetCampIds = campIds && campIds.length > 0 ? campIds : campId ? [campId] : [];\n  if (targetCampIds.length === 0) {\n    return res.status(400).json({ error: "campId ou campIds requis." });\n  }\n\n  const memberships = await prisma.campMembership.findMany({\n    where: { userId: req.userId, campId: { in: targetCampIds } },\n  });\n  if (memberships.length !== targetCampIds.length) {\n    return res.status(403).json({ error: "Tu n\'es pas membre de tous ces camps." });\n  }\n\n  const day = toDayStart(date ? new Date(date) : new Date());\n\n  const logs = await Promise.all(\n    targetCampIds.map((cId) =>\n      prisma.exerciseLog.upsert({\n        where: { userId_campId_exerciseId_date: { userId: req.userId!, campId: cId, exerciseId, date: day } },\n        create: { userId: req.userId!, campId: cId, exerciseId, date: day, setsDone, valueDone, completed: true },\n        update: { setsDone, valueDone, completed: true },\n      })\n    )\n  );\n\n  const newBadges = await checkAndAwardBadges(req.userId!);\n\n  res.status(201).json({ log: logs[0], logs, newBadges });\n});\n\n// Permet d\'annuler un log (ex: coche par erreur)\nrouter.delete("/", async (req: AuthRequest, res) => {\n  const campId = req.query.campId as string;\n  const exerciseId = req.query.exerciseId as string;\n  const dateStr = req.query.date as string | undefined;\n  if (!campId || !exerciseId) {\n    return res.status(400).json({ error: "campId et exerciseId sont requis." });\n  }\n  const day = toDayStart(dateStr ? new Date(dateStr) : new Date());\n\n  await prisma.exerciseLog.deleteMany({\n    where: { userId: req.userId, campId, exerciseId, date: day },\n  });\n  res.status(204).send();\n});\n\nexport default router;\n'
FILES['backend/src/index.ts'] = 'import "dotenv/config";\nimport express from "express";\nimport cors from "cors";\n\nimport authRoutes from "./routes/auth";\nimport userRoutes from "./routes/users";\nimport exerciseRoutes from "./routes/exercises";\nimport campRoutes from "./routes/camps";\nimport campExerciseRoutes from "./routes/campExercises";\nimport todayRoutes from "./routes/today";\nimport logRoutes from "./routes/logs";\nimport progressRoutes from "./routes/progress";\nimport pushRoutes from "./routes/push";\nimport badgeRoutes from "./routes/badges";\nimport campMessageRoutes from "./routes/campMessages";\nimport messageRoutes from "./routes/messages";\nimport campCircuitRoutes from "./routes/campCircuits";\nimport chronoSessionRoutes from "./routes/chronoSessions";\nimport activityRoutes from "./routes/activity";\nimport restDayRoutes from "./routes/restDays";\nimport reactionRoutes from "./routes/reactions";\nimport favoriteCircuitRoutes from "./routes/favoriteCircuits";\nimport connectionRoutes from "./routes/connections";\nimport { initPush, scheduleReminders } from "./services/notifications";\n\nconst app = express();\n\napp.use(cors({ origin: process.env.FRONTEND_URL || "*" }));\napp.use(express.json());\n\napp.get("/api/health", (_req, res) => res.json({ status: "ok" }));\n\napp.use("/api/auth", authRoutes);\napp.use("/api/users", userRoutes);\napp.use("/api/exercises", exerciseRoutes);\napp.use("/api/camps", campRoutes);\napp.use("/api/camp-exercises", campExerciseRoutes);\napp.use("/api/today", todayRoutes);\napp.use("/api/logs", logRoutes);\napp.use("/api/progress", progressRoutes);\napp.use("/api/push", pushRoutes);\napp.use("/api/badges", badgeRoutes);\napp.use("/api/camps", campMessageRoutes);\napp.use("/api/messages", messageRoutes);\napp.use("/api/camp-circuits", campCircuitRoutes);\napp.use("/api/chrono-sessions", chronoSessionRoutes);\napp.use("/api/activity", activityRoutes);\napp.use("/api/rest-days", restDayRoutes);\napp.use("/api/reactions", reactionRoutes);\napp.use("/api/favorite-circuits", favoriteCircuitRoutes);\napp.use("/api/connections", connectionRoutes);\n\n// Gestion d\'erreur generique (evite qu\'une exception fasse planter le process)\napp.use((err: any, _req: express.Request, res: express.Response, _next: express.NextFunction) => {\n  console.error(err);\n  res.status(500).json({ error: "Erreur interne du serveur." });\n});\n\nconst port = Number(process.env.PORT || 4000);\n\ninitPush();\nscheduleReminders();\n\napp.listen(port, () => {\n  console.log(`API demarree sur http://localhost:${port}`);\n});\n'
FILES['frontend/src/context/AuthContext.tsx'] = 'import { createContext, useContext, useEffect, useState, ReactNode } from "react";\nimport { api } from "../api/client";\n\nexport interface UserProfile {\n  id: string;\n  email: string;\n  name: string;\n  weightKg: number | null;\n  heightCm: number | null;\n  birthDate: string | null;\n  sex: string | null;\n  sport: string | null;\n  sportLevel: string | null;\n  avatarBase64: string | null;\n  location: string | null;\n  equipment: string | null;\n}\n\ninterface AuthContextValue {\n  user: UserProfile | null;\n  loading: boolean;\n  login: (email: string, password: string) => Promise<void>;\n  register: (\n    email: string,\n    password: string,\n    name: string,\n    sport?: string | null,\n    sportLevel?: string | null\n  ) => Promise<void>;\n  logout: () => void;\n  refreshUser: () => Promise<void>;\n}\n\nconst AuthContext = createContext<AuthContextValue | undefined>(undefined);\n\nexport function AuthProvider({ children }: { children: ReactNode }) {\n  const [user, setUser] = useState<UserProfile | null>(null);\n  const [loading, setLoading] = useState(true);\n\n  async function refreshUser() {\n    try {\n      const me = await api.get<UserProfile>("/users/me");\n      setUser(me);\n    } catch {\n      setUser(null);\n      localStorage.removeItem("token");\n    }\n  }\n\n  useEffect(() => {\n    const token = localStorage.getItem("token");\n    if (!token) {\n      setLoading(false);\n      return;\n    }\n    refreshUser().finally(() => setLoading(false));\n  }, []);\n\n  async function login(email: string, password: string) {\n    const res = await api.post<{ token: string; user: UserProfile }>("/auth/login", { email, password });\n    localStorage.setItem("token", res.token);\n    setUser(res.user);\n  }\n\n  async function register(\n    email: string,\n    password: string,\n    name: string,\n    sport?: string | null,\n    sportLevel?: string | null\n  ) {\n    const res = await api.post<{ token: string; user: UserProfile }>("/auth/register", {\n      email,\n      password,\n      name,\n      sport: sport || null,\n      sportLevel: sportLevel || null,\n    });\n    localStorage.setItem("token", res.token);\n    setUser(res.user);\n  }\n\n  function logout() {\n    localStorage.removeItem("token");\n    setUser(null);\n  }\n\n  return (\n    <AuthContext.Provider value={{ user, loading, login, register, logout, refreshUser }}>\n      {children}\n    </AuthContext.Provider>\n  );\n}\n\nexport function useAuth() {\n  const ctx = useContext(AuthContext);\n  if (!ctx) throw new Error("useAuth doit être utilisé dans un AuthProvider");\n  return ctx;\n}\n'
FILES['frontend/src/lib/equipment.ts'] = 'export const EQUIPMENT_CATALOG = [\n  { key: "AUCUN", label: "Aucun materiel (poids du corps)" },\n  { key: "HALTERES", label: "Halteres / poids libres" },\n  { key: "BARRE_TRACTION", label: "Barre de traction" },\n  { key: "ELASTIQUE", label: "Elastique de resistance" },\n  { key: "BANC", label: "Banc de musculation" },\n  { key: "KETTLEBELL", label: "Kettlebell" },\n  { key: "CORDE_A_SAUTER", label: "Corde a sauter" },\n  { key: "TAPIS", label: "Tapis de sol" },\n  { key: "VELO", label: "Velo / home trainer" },\n  { key: "AUTRE", label: "Autre materiel specifique" },\n];\n\nexport const CATEGORY_CATALOG = [\n  { key: "UPPER", label: "Membres superieurs" },\n  { key: "LOWER", label: "Membres inferieurs" },\n  { key: "ABS", label: "Abdominaux / gainage" },\n  { key: "CARDIO", label: "Cardio" },\n  { key: "FULL_BODY", label: "Tout le corps" },\n  { key: "MOBILITY", label: "Mobilite / etirements" },\n];\n'
FILES['frontend/src/pages/CreateCamp.tsx'] = 'import { FormEvent, useState } from "react";\nimport { useNavigate } from "react-router-dom";\nimport { api, ApiError } from "../api/client";\nimport ExercisePicker from "../components/ExercisePicker";\n\nexport default function CreateCamp() {\n  const navigate = useNavigate();\n  const [name, setName] = useState("");\n  const [description, setDescription] = useState("");\n  const [selected, setSelected] = useState<string[]>([]);\n  const [startDate, setStartDate] = useState("");\n  const [endDate, setEndDate] = useState("");\n  const [creatorRole, setCreatorRole] = useState<"PLAYER" | "COACH">("PLAYER");\n  const [error, setError] = useState<string | null>(null);\n  const [busy, setBusy] = useState(false);\n  const [createdCode, setCreatedCode] = useState<string | null>(null);\n  const [createdId, setCreatedId] = useState<string | null>(null);\n  const [copied, setCopied] = useState(false);\n\n  async function onSubmit(e: FormEvent) {\n    e.preventDefault();\n    setError(null);\n    if (selected.length === 0) {\n      setError("Selectionne au moins un exercice.");\n      return;\n    }\n    if (startDate && endDate && endDate < startDate) {\n      setError("La date de fin doit être après la date de debut.");\n      return;\n    }\n    setBusy(true);\n    try {\n      const camp = await api.post<{ id: string; code: string }>("/camps", {\n        name,\n        description: description.trim() || null,\n        exerciseIds: selected,\n        startDate: startDate || null,\n        endDate: endDate || null,\n        creatorRole,\n      });\n      setCreatedCode(camp.code);\n      setCreatedId(camp.id);\n    } catch (err) {\n      setError(err instanceof ApiError ? err.message : "Impossible de créer le camp.");\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  async function copyCode() {\n    if (!createdCode) return;\n    await navigator.clipboard.writeText(createdCode);\n    setCopied(true);\n    setTimeout(() => setCopied(false), 2000);\n  }\n\n  if (createdCode && createdId) {\n    return (\n      <div className="max-w-md">\n        <h1 className="font-display text-3xl uppercase tracking-wide mb-1">Camp créé !</h1>\n        <p className="text-muted text-sm mb-6">\n          Partage ce code pour inviter d\'autres personnes a rejoindre "{name}".\n        </p>\n        <div className="bg-surface border-2 border-dashed border-accent rounded-xl p-6 text-center mb-6">\n          <p className="text-xs uppercase tracking-widest text-muted mb-2">Code d\'invitation</p>\n          <p className="font-mono text-4xl tracking-[0.3em] text-accent mb-3">{createdCode}</p>\n          <button\n            onClick={copyCode}\n            className="text-sm bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-3 py-1.5"\n          >\n            {copied ? "Copie !" : "📋 Copier le code"}\n          </button>\n        </div>\n        <button\n          onClick={() => navigate(`/camps/${createdId}`)}\n          className="w-full bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md py-2"\n        >\n          Definir les consignes des exercices\n        </button>\n      </div>\n    );\n  }\n\n  return (\n    <div className="max-w-xl">\n      <h1 className="font-display text-3xl uppercase tracking-wide mb-1">Nouveau camp</h1>\n      <p className="text-muted text-sm mb-6">\n        Choisis un nom et les exercices qui feront partie de ce camp. En tant que créateur, tu definiras ensuite\n        la consigne (objectif, fréquence) suivie par tous les membres.\n      </p>\n\n      <form onSubmit={onSubmit} className="space-y-5">\n        <div>\n          <label className="block text-sm text-muted mb-1" htmlFor="name">\n            Nom du camp\n          </label>\n          <input\n            id="name"\n            required\n            value={name}\n            onChange={(e) => setName(e.target.value)}\n            placeholder="Ex : Preparation pompiers volontaires"\n            className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n          />\n        </div>\n\n        <div>\n          <label className="block text-sm text-muted mb-1" htmlFor="description">\n            Descriptif du camp (optionnel)\n          </label>\n          <textarea\n            id="description"\n            value={description}\n            onChange={(e) => setDescription(e.target.value)}\n            placeholder="Ex : Preparation physique pour les tests d\'entree pompiers volontaires..."\n            rows={3}\n            className="w-full bg-surface2 border border-border rounded-md px-3 py-2 resize-none"\n          />\n        </div>\n\n        <div>\n          <label className="block text-sm text-muted mb-2">Ton role dans ce camp</label>\n          <div className="grid grid-cols-2 gap-2">\n            <button\n              type="button"\n              onClick={() => setCreatorRole("PLAYER")}\n              className={`text-left p-3 rounded-md border ${\n                creatorRole === "PLAYER" ? "bg-accent/15 border-accent" : "bg-surface2 border-border"\n              }`}\n            >\n              <p className="text-sm font-medium">🏃 Coequipier</p>\n              <p className="text-xs text-muted mt-0.5">Je fais aussi les exercices, comme les autres membres.</p>\n            </button>\n            <button\n              type="button"\n              onClick={() => setCreatorRole("COACH")}\n              className={`text-left p-3 rounded-md border ${\n                creatorRole === "COACH" ? "bg-accent/15 border-accent" : "bg-surface2 border-border"\n              }`}\n            >\n              <p className="text-sm font-medium">📋 Entraineur</p>\n              <p className="text-xs text-muted mt-0.5">\n                Je ne fais pas les exercices, mais je vois la participation des autres.\n              </p>\n            </button>\n          </div>\n        </div>\n\n        <div>\n          <label className="block text-sm text-muted mb-2">Exercices du camp</label>\n          <ExercisePicker selected={selected} onChange={setSelected} />\n        </div>\n\n        <div className="grid grid-cols-2 gap-4">\n          <div>\n            <label className="block text-sm text-muted mb-1" htmlFor="startDate">\n              Date de debut (optionnel)\n            </label>\n            <input\n              id="startDate"\n              type="date"\n              value={startDate}\n              onChange={(e) => setStartDate(e.target.value)}\n              className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n            />\n          </div>\n          <div>\n            <label className="block text-sm text-muted mb-1" htmlFor="endDate">\n              Date de fin (optionnel)\n            </label>\n            <input\n              id="endDate"\n              type="date"\n              value={endDate}\n              onChange={(e) => setEndDate(e.target.value)}\n              className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n            />\n          </div>\n        </div>\n\n        {error && <p className="text-sm text-accent">{error}</p>}\n\n        <button\n          type="submit"\n          disabled={busy}\n          className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-5 py-2 disabled:opacity-60"\n        >\n          {busy ? "Création..." : "Créer le camp"}\n        </button>\n      </form>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/CampDetail.tsx'] = 'import { useEffect, useState } from "react";\nimport { Link, useNavigate, useParams } from "react-router-dom";\nimport { api } from "../api/client";\nimport { useAuth } from "../context/AuthContext";\nimport ProgramForm, { Program } from "../components/ProgramForm";\nimport CampCircuitForm, { CampCircuitData } from "../components/CampCircuitForm";\nimport CircuitRunner from "../components/CircuitRunner";\nimport ReactionPicker, { ReactionSummary } from "../components/ReactionPicker";\nimport { secondsToMMSS } from "../lib/duration";\n\ninterface FeedItem {\n  targetType: "exercise" | "circuit";\n  targetId: string;\n  userId: string;\n  userName: string;\n  label: string;\n  date: string;\n  setsDone: number | null;\n  valueDone: number | null;\n  unit: "REPS" | "SECONDS" | null;\n  durationSeconds: number | null;\n  reactions: ReactionSummary[];\n}\n\ninterface CampExerciseData extends Program {\n  exercise: { id: string; name: string; unit: "REPS" | "SECONDS"; description: string | null };\n}\n\ninterface CampDetailData {\n  id: string;\n  name: string;\n  description: string | null;\n  code: string;\n  createdById: string;\n  startDate: string | null;\n  endDate: string | null;\n  isEnded: boolean;\n  myRole: "COACH" | "PLAYER";\n  exercises: CampExerciseData[];\n  circuits: CampCircuitData[];\n  members: { user: { id: string; name: string } }[];\n}\n\ninterface CatalogExercise {\n  id: string;\n  name: string;\n}\n\nconst RECURRENCE_LABEL: Record<\n  string,\n  (p: { recurrenceType: string; daysOfWeek: string | null; intervalDays: number | null; timesPerWeek?: number | null }) => string\n> = {\n  DAILY: () => "Tous les jours",\n  WEEKLY: (p) => {\n    const days = p.daysOfWeek ? (JSON.parse(p.daysOfWeek) as number[]) : [];\n    const names = ["Dim", "Lun", "Mar", "Mer", "Jeu", "Ven", "Sam"];\n    return days.map((d) => names[d]).join(", ");\n  },\n  EVERY_N_DAYS: (p) => `Tous les ${p.intervalDays} jours`,\n  WEEKLY_COUNT: (p) => `${p.timesPerWeek}x/semaine (jours libres)`,\n};\n\nconst QUICK_CHRONO_REST_SECONDS = 15;\n\nexport default function CampDetail() {\n  const { id } = useParams<{ id: string }>();\n  const navigate = useNavigate();\n  const { user } = useAuth();\n  const [camp, setCamp] = useState<CampDetailData | null>(null);\n  const [catalog, setCatalog] = useState<CatalogExercise[]>([]);\n  const [editingExerciseId, setEditingExerciseId] = useState<string | null>(null);\n  const [editingDescription, setEditingDescription] = useState(false);\n  const [descriptionDraft, setDescriptionDraft] = useState("");\n  const [savingDescription, setSavingDescription] = useState(false);\n  const [confirmingDelete, setConfirmingDelete] = useState(false);\n  const [deleting, setDeleting] = useState(false);\n  const [editingCircuitId, setEditingCircuitId] = useState<string | null>(null);\n  const [creatingCircuit, setCreatingCircuit] = useState(false);\n  const [runningCircuit, setRunningCircuit] = useState<CampCircuitData | null>(null);\n  const [runningExercise, setRunningExercise] = useState<CampExerciseData | null>(null);\n  const [feed, setFeed] = useState<FeedItem[] | null>(null);\n  const [duplicating, setDuplicating] = useState(false);\n  const [codeCopied, setCodeCopied] = useState(false);\n\n  async function copyCode() {\n    if (!camp) return;\n    await navigator.clipboard.writeText(camp.code);\n    setCodeCopied(true);\n    setTimeout(() => setCodeCopied(false), 2000);\n  }\n\n  function loadFeed() {\n    if (!id) return;\n    api.get<FeedItem[]>(`/camps/${id}/feed`).then(setFeed);\n  }\n\n  async function duplicateCamp() {\n    if (!camp) return;\n    setDuplicating(true);\n    try {\n      const created = await api.post<{ id: string }>(`/camps/${camp.id}/duplicate`, {});\n      navigate(`/camps/${created.id}`);\n    } finally {\n      setDuplicating(false);\n    }\n  }\n\n  function load() {\n    if (!id) return;\n    api.get<CampDetailData>(`/camps/${id}`).then(setCamp);\n  }\n  useEffect(load, [id]);\n  useEffect(loadFeed, [id]);\n  useEffect(() => {\n    api.get<CatalogExercise[]>("/exercises").then(setCatalog);\n  }, []);\n\n  async function deleteCamp() {\n    if (!camp) return;\n    setDeleting(true);\n    try {\n      await api.del(`/camps/${camp.id}`);\n      navigate("/camps");\n    } finally {\n      setDeleting(false);\n    }\n  }\n\n  async function saveDescription() {\n    if (!camp) return;\n    setSavingDescription(true);\n    try {\n      await api.put(`/camps/${camp.id}`, { description: descriptionDraft.trim() || null });\n      setEditingDescription(false);\n      load();\n    } finally {\n      setSavingDescription(false);\n    }\n  }\n\n  async function deleteCircuit(circuitId: string) {\n    await api.del(`/camp-circuits/${circuitId}`);\n    load();\n  }\n\n  async function onExerciseChronoComplete(ce: CampExerciseData) {\n    await api.post("/logs", { campId: id, exerciseId: ce.exercise.id, setsDone: ce.targetSets, valueDone: ce.targetValue ?? 0 });\n    setRunningExercise(null);\n    load();\n  }\n\n  async function onCircuitChronoComplete(circuit: CampCircuitData, totalDurationSeconds: number) {\n    await api.post(`/camp-circuits/${circuit.id}/log`, { durationSeconds: totalDurationSeconds });\n    setRunningCircuit(null);\n    load();\n  }\n\n  if (!camp) return <p className="text-muted">Chargement...</p>;\n\n  const isCoach = user?.id === camp.createdById;\n\n  if (runningExercise) {\n    return (\n      <div className="max-w-md mx-auto">\n        <CircuitRunner\n          items={[{ name: runningExercise.exercise.name }]}\n          workSeconds={runningExercise.targetValue ?? 30}\n          restSeconds={0}\n          rounds={runningExercise.targetSets}\n          roundRestSeconds={QUICK_CHRONO_REST_SECONDS}\n          onComplete={() => onExerciseChronoComplete(runningExercise)}\n          onCancel={() => setRunningExercise(null)}\n        />\n      </div>\n    );\n  }\n\n  if (runningCircuit) {\n    const circuitItems = JSON.parse(runningCircuit.items) as { name: string }[];\n    return (\n      <div className="max-w-md mx-auto">\n        <CircuitRunner\n          items={circuitItems}\n          workSeconds={runningCircuit.workSeconds}\n          restSeconds={runningCircuit.restSeconds}\n          rounds={runningCircuit.rounds}\n          roundRestSeconds={runningCircuit.roundRestSeconds}\n          onComplete={(duration) => onCircuitChronoComplete(runningCircuit, duration)}\n          onCancel={() => setRunningCircuit(null)}\n        />\n      </div>\n    );\n  }\n\n  return (\n    <div className="max-w-2xl">\n      <div className="flex items-start justify-between flex-wrap gap-3 mb-2">\n        <div>\n          <div className="flex items-center gap-2 flex-wrap">\n            <h1 className="font-display text-3xl uppercase tracking-wide">{camp.name}</h1>\n            {camp.isEnded && (\n              <span className="text-[10px] uppercase tracking-wide bg-surface2 border border-border rounded px-2 py-0.5 text-muted">\n                Termine\n              </span>\n            )}\n            <span className="text-[10px] uppercase tracking-wide bg-accent/15 text-accent rounded px-2 py-0.5">\n              {camp.myRole === "COACH" ? "Entraineur" : "Coequipier"}\n            </span>\n          </div>\n          <p className="text-muted text-sm">\n            {camp.members.length} membre{camp.members.length > 1 ? "s" : ""} :{" "}\n            {camp.members.map((m) => m.user.name).join(", ")}\n          </p>\n          {(camp.startDate || camp.endDate) && (\n            <p className="text-muted text-xs mt-1">\n              {camp.startDate ? `Du ${new Date(camp.startDate).toLocaleDateString("fr-FR")}` : "Sans date de debut"}\n              {camp.endDate ? ` au ${new Date(camp.endDate).toLocaleDateString("fr-FR")}` : ""}\n            </p>\n          )}\n        </div>\n        <div className="bg-surface border border-border rounded-md px-3 py-2 text-center">\n          <p className="text-[10px] uppercase tracking-widest text-muted">Code</p>\n          <p className="font-mono text-lg text-accent mb-1">{camp.code}</p>\n          <button onClick={copyCode} className="text-[10px] text-muted hover:text-accent">\n            {codeCopied ? "Copie !" : "📋 Copier"}\n          </button>\n        </div>\n      </div>\n\n      <div className="flex items-center gap-4 flex-wrap mt-2">\n        <Link to={`/camps/${camp.id}/discussion`} className="text-sm text-accent hover:text-accentSoft">\n          💬 Discussion du camp\n        </Link>\n        <Link to={`/camps/${camp.id}/classement`} className="text-sm text-accent hover:text-accentSoft">\n          📊 Classement (régularité)\n        </Link>\n        <Link to={`/camps/${camp.id}/calendrier`} className="text-sm text-accent hover:text-accentSoft">\n          🗓️ Calendrier\n        </Link>\n        {isCoach && (\n          <>\n            <button onClick={duplicateCamp} disabled={duplicating} className="text-sm text-muted hover:text-accent">\n              {duplicating ? "Duplication..." : "Dupliquer le camp"}\n            </button>\n            <button onClick={() => setConfirmingDelete(true)} className="text-sm text-muted hover:text-accent ml-auto">\n              Supprimer le camp\n            </button>\n          </>\n        )}\n      </div>\n\n      {confirmingDelete && (\n        <div className="bg-surface border border-accent rounded-lg p-4 mt-3">\n          <p className="text-sm mb-3">\n            Supprimer definitivement le camp "{camp.name}" ? Cette action est irreversible : l\'historique des\n            séances de tous les membres pour ce camp sera perdu.\n          </p>\n          <div className="flex gap-2">\n            <button\n              onClick={deleteCamp}\n              disabled={deleting}\n              className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-3 py-1.5 text-sm disabled:opacity-60"\n            >\n              {deleting ? "Suppression..." : "Oui, supprimer"}\n            </button>\n            <button onClick={() => setConfirmingDelete(false)} className="text-muted hover:text-text text-sm px-2">\n              Annuler\n            </button>\n          </div>\n        </div>\n      )}\n\n      <div className="mt-4">\n        {editingDescription ? (\n          <div className="bg-surface2 border border-border rounded-lg p-3">\n            <textarea\n              value={descriptionDraft}\n              onChange={(e) => setDescriptionDraft(e.target.value)}\n              placeholder="Descriptif du camp..."\n              rows={3}\n              className="w-full bg-surface border border-border rounded-md px-2 py-1.5 text-sm resize-none mb-2"\n            />\n            <div className="flex gap-2">\n              <button\n                onClick={saveDescription}\n                disabled={savingDescription}\n                className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-3 py-1.5 text-sm disabled:opacity-60"\n              >\n                {savingDescription ? "Enregistrement..." : "Enregistrer"}\n              </button>\n              <button onClick={() => setEditingDescription(false)} className="text-muted hover:text-text text-sm px-2">\n                Annuler\n              </button>\n            </div>\n          </div>\n        ) : camp.description ? (\n          <div className="flex items-start justify-between gap-3">\n            <p className="text-sm text-muted italic">{camp.description}</p>\n            {isCoach && (\n              <button\n                onClick={() => {\n                  setDescriptionDraft(camp.description ?? "");\n                  setEditingDescription(true);\n                }}\n                className="text-xs text-accent hover:text-accentSoft shrink-0"\n              >\n                Modifier\n              </button>\n            )}\n          </div>\n        ) : (\n          isCoach && (\n            <button\n              onClick={() => {\n                setDescriptionDraft("");\n                setEditingDescription(true);\n              }}\n              className="text-xs text-accent hover:text-accentSoft"\n            >\n              + Ajouter un descriptif au camp\n            </button>\n          )\n        )}\n      </div>\n\n      <h2 className="font-display uppercase tracking-wide text-lg mt-8 mb-1">Exercices du camp</h2>\n      <p className="text-muted text-sm mb-4">\n        {isCoach\n          ? "En tant que créateur du camp, tu définis la consigne (objectif, fréquence) suivie par tous les membres."\n          : "Consignes définies par le créateur du camp."}\n      </p>\n\n      <div className="space-y-3">\n        {camp.exercises.map((ce) => {\n          const isEditing = editingExerciseId === ce.exercise.id;\n\n          if (isEditing) {\n            return (\n              <ProgramForm\n                key={ce.exercise.id}\n                campId={camp.id}\n                exerciseId={ce.exercise.id}\n                exerciseName={ce.exercise.name}\n                unit={ce.exercise.unit}\n                existing={ce}\n                onSaved={() => {\n                  setEditingExerciseId(null);\n                  load();\n                }}\n                onCancel={() => setEditingExerciseId(null)}\n              />\n            );\n          }\n\n          const unitLabel = ce.exercise.unit === "REPS" ? "reps" : "";\n          const valueLabel =\n            ce.exercise.unit === "SECONDS" && ce.targetValue != null\n              ? secondsToMMSS(ce.targetValue)\n              : `${ce.targetValue} ${unitLabel}`;\n          const canQuickChrono = ce.exercise.unit === "SECONDS" && ce.targetMode === "FIXED";\n\n          return (\n            <div key={ce.exercise.id} className="bg-surface border border-border rounded-lg p-4">\n              <div className="flex items-center justify-between flex-wrap gap-3">\n                <div>\n                  <p className="font-medium">{ce.exercise.name}</p>\n                  <p className="text-sm text-muted">\n                    {ce.targetMode === "MAX"\n                      ? `${ce.targetSets} serie${ce.targetSets > 1 ? "s" : ""} à fond`\n                      : `${ce.targetSets} x ${valueLabel}`}{" "}\n                    · {RECURRENCE_LABEL[ce.recurrenceType](ce)}\n                  </p>\n                  {ce.description && <p className="text-xs text-muted mt-1 italic">"{ce.description}"</p>}\n                </div>\n                <div className="flex gap-3 items-center shrink-0">\n                  {canQuickChrono && (\n                    <button\n                      onClick={() => setRunningExercise(ce)}\n                      title="Lancer le chrono pour cet exercice"\n                      className="w-9 h-9 rounded-full flex items-center justify-center border-2 border-accent text-accent hover:bg-accent/10"\n                    >\n                      ⏱\n                    </button>\n                  )}\n                  <Link\n                    to={`/camps/${camp.id}/progression/${ce.exercise.id}`}\n                    className="text-sm text-accent hover:text-accentSoft"\n                  >\n                    Progression\n                  </Link>\n                  {isCoach && (\n                    <button\n                      onClick={() => setEditingExerciseId(ce.exercise.id)}\n                      className="text-sm bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-3 py-1.5"\n                    >\n                      Modifier\n                    </button>\n                  )}\n                </div>\n              </div>\n            </div>\n          );\n        })}\n      </div>\n\n      <div className="flex items-center justify-between mt-8 mb-1">\n        <h2 className="font-display uppercase tracking-wide text-lg">Circuits training du camp</h2>\n        {isCoach && !creatingCircuit && (\n          <button onClick={() => setCreatingCircuit(true)} className="text-sm text-accent hover:text-accentSoft">\n            + Nouveau circuit\n          </button>\n        )}\n      </div>\n      <p className="text-muted text-sm mb-4">\n        Enchainements guides au chrono, alternative aux exercices individuels.\n      </p>\n\n      {creatingCircuit && (\n        <div className="mb-3">\n          <CampCircuitForm\n            campId={camp.id}\n            catalog={catalog}\n            onSaved={() => {\n              setCreatingCircuit(false);\n              load();\n            }}\n            onCancel={() => setCreatingCircuit(false)}\n          />\n        </div>\n      )}\n\n      <div className="space-y-3">\n        {camp.circuits.map((circuit) => {\n          if (editingCircuitId === circuit.id) {\n            return (\n              <CampCircuitForm\n                key={circuit.id}\n                campId={camp.id}\n                catalog={catalog}\n                existing={circuit}\n                onSaved={() => {\n                  setEditingCircuitId(null);\n                  load();\n                }}\n                onCancel={() => setEditingCircuitId(null)}\n              />\n            );\n          }\n          const circuitItems = JSON.parse(circuit.items) as { name: string }[];\n          return (\n            <div key={circuit.id} className="bg-surface border border-border rounded-lg p-4">\n              <div className="flex items-center justify-between flex-wrap gap-3">\n                <div>\n                  <p className="font-medium">🔁 {circuit.name}</p>\n                  <p className="text-sm text-muted">\n                    {circuitItems.map((i) => i.name).join(", ")} · {circuit.rounds} tour{circuit.rounds > 1 ? "s" : ""} ·{" "}\n                    {RECURRENCE_LABEL[circuit.recurrenceType](circuit)}\n                  </p>\n                  {circuit.description && <p className="text-xs text-muted mt-1 italic">"{circuit.description}"</p>}\n                </div>\n                <div className="flex gap-2 items-center shrink-0">\n                  <button\n                    onClick={() => setRunningCircuit(circuit)}\n                    className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-3 py-1.5 text-sm"\n                  >\n                    ⏱ Lancer\n                  </button>\n                  {isCoach && (\n                    <>\n                      <button\n                        onClick={() => setEditingCircuitId(circuit.id)}\n                        className="text-sm bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-3 py-1.5"\n                      >\n                        Modifier\n                      </button>\n                      <button onClick={() => deleteCircuit(circuit.id)} className="text-muted hover:text-accent text-sm">\n                        Suppr.\n                      </button>\n                    </>\n                  )}\n                </div>\n              </div>\n            </div>\n          );\n        })}\n        {camp.circuits.length === 0 && !creatingCircuit && (\n          <p className="text-muted text-sm italic">Aucun circuit pour l\'instant.</p>\n        )}\n      </div>\n\n      <h2 className="font-display uppercase tracking-wide text-lg mt-8 mb-1">Fil d\'activité</h2>\n      <p className="text-muted text-sm mb-4">\n        Les dernières séances validees par les membres du camp — pour s\'encourager, pas pour comparer.\n      </p>\n      <div className="space-y-2">\n        {feed === null && <p className="text-muted text-sm">Chargement...</p>}\n        {feed?.length === 0 && <p className="text-muted text-sm italic">Aucune activité pour l\'instant.</p>}\n        {feed?.map((item) => (\n          <div key={`${item.targetType}-${item.targetId}`} className="bg-surface border border-border rounded-lg p-3">\n            <p className="text-sm">\n              <span className="font-medium">{item.userName}</span> a validé{" "}\n              <span className="text-muted">{item.label}</span>\n              {item.targetType === "exercise" && item.setsDone != null && item.valueDone != null && (\n                <span className="text-muted">\n                  {" "}\n                  ({item.setsDone} x {item.unit === "SECONDS" ? secondsToMMSS(item.valueDone) : `${item.valueDone} reps`})\n                </span>\n              )}\n              {item.targetType === "circuit" && item.durationSeconds != null && (\n                <span className="text-muted"> ({secondsToMMSS(item.durationSeconds)})</span>\n              )}\n            </p>\n            <div className="flex items-center justify-between mt-2">\n              <p className="text-[10px] text-muted">\n                {new Date(item.date).toLocaleDateString("fr-FR", { day: "2-digit", month: "short" })}\n              </p>\n              <ReactionPicker\n                targetType={item.targetType}\n                targetId={item.targetId}\n                reactions={item.reactions}\n                onChange={loadFeed}\n              />\n            </div>\n          </div>\n        ))}\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/JoinCamp.tsx'] = 'import { FormEvent, useState } from "react";\nimport { useNavigate } from "react-router-dom";\nimport { api, ApiError } from "../api/client";\nimport { useAuth } from "../context/AuthContext";\nimport { EQUIPMENT_CATALOG } from "../lib/equipment";\n\ninterface CampPreview {\n  id: string;\n  name: string;\n  description: string | null;\n  memberCount: number;\n  exerciseNames: string[];\n  requiredEquipment: string[];\n}\n\nexport default function JoinCamp() {\n  const navigate = useNavigate();\n  const { user } = useAuth();\n  const [code, setCode] = useState("");\n  const [preview, setPreview] = useState<CampPreview | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const [busy, setBusy] = useState(false);\n\n  const myEquipment: string[] = user?.equipment ? JSON.parse(user.equipment) : [];\n  const missingEquipment = preview?.requiredEquipment.filter((eq) => eq !== "AUCUN" && !myEquipment.includes(eq)) ?? [];\n\n  async function onPreview(e: FormEvent) {\n    e.preventDefault();\n    setError(null);\n    setBusy(true);\n    try {\n      const res = await api.get<CampPreview>(`/camps/preview?code=${encodeURIComponent(code)}`);\n      setPreview(res);\n    } catch (err) {\n      setError(err instanceof ApiError ? err.message : "Impossible de trouver ce camp.");\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  async function confirmJoin() {\n    if (!preview) return;\n    setError(null);\n    setBusy(true);\n    try {\n      const res = await api.post<{ campId: string }>("/camps/join", { code });\n      navigate(`/camps/${res.campId}`);\n    } catch (err) {\n      setError(err instanceof ApiError ? err.message : "Impossible de rejoindre ce camp.");\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  function equipmentLabel(key: string): string {\n    return EQUIPMENT_CATALOG.find((e) => e.key === key)?.label ?? key;\n  }\n\n  if (preview) {\n    return (\n      <div className="max-w-sm">\n        <h1 className="font-display text-3xl uppercase tracking-wide mb-1">{preview.name}</h1>\n        {preview.description && <p className="text-muted text-sm mb-3 italic">"{preview.description}"</p>}\n        <p className="text-muted text-sm mb-4">\n          {preview.memberCount} membre{preview.memberCount > 1 ? "s" : ""} · {preview.exerciseNames.join(", ")}\n        </p>\n\n        {missingEquipment.length > 0 && (\n          <div className="bg-surface2 border border-accent rounded-lg p-3 mb-4">\n            <p className="text-sm mb-1">⚠️ Materiel manquant selon ton profil :</p>\n            <p className="text-sm text-muted">{missingEquipment.map(equipmentLabel).join(", ")}</p>\n            <p className="text-xs text-muted mt-2">Tu peux quand meme rejoindre le camp si tu le souhaites.</p>\n          </div>\n        )}\n\n        {error && <p className="text-sm text-accent mb-3">{error}</p>}\n\n        <div className="flex gap-2">\n          <button\n            onClick={confirmJoin}\n            disabled={busy}\n            className="flex-1 bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md py-2 disabled:opacity-60"\n          >\n            {busy ? "Inscription..." : "Rejoindre quand meme"}\n          </button>\n          <button onClick={() => setPreview(null)} className="text-muted hover:text-text text-sm px-3">\n            Annuler\n          </button>\n        </div>\n      </div>\n    );\n  }\n\n  return (\n    <div className="max-w-sm">\n      <h1 className="font-display text-3xl uppercase tracking-wide mb-1">Rejoindre un camp</h1>\n      <p className="text-muted text-sm mb-6">Entre le code partage par la personne qui a créé le camp.</p>\n\n      <form onSubmit={onPreview} className="space-y-4">\n        <input\n          required\n          value={code}\n          onChange={(e) => setCode(e.target.value.toUpperCase())}\n          placeholder="EX: 4F7QRT"\n          className="w-full bg-surface2 border border-border rounded-md px-3 py-3 font-mono text-2xl tracking-[0.2em] text-center uppercase"\n          maxLength={8}\n        />\n\n        {error && <p className="text-sm text-accent">{error}</p>}\n\n        <button\n          type="submit"\n          disabled={busy}\n          className="w-full bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md py-2 disabled:opacity-60"\n        >\n          {busy ? "Verification..." : "Rejoindre"}\n        </button>\n      </form>\n    </div>\n  );\n}\n'
FILES['frontend/src/components/ExercisePicker.tsx'] = 'import { useEffect, useMemo, useRef, useState } from "react";\nimport { api } from "../api/client";\nimport { resizeImageFile } from "../lib/image";\nimport { CATEGORY_CATALOG, EQUIPMENT_CATALOG } from "../lib/equipment";\n\nexport interface Exercise {\n  id: string;\n  name: string;\n  description: string | null;\n  unit: "REPS" | "SECONDS";\n  category?: string | null;\n  equipment?: string | null;\n  isCustom: boolean;\n}\n\ninterface Props {\n  selected: string[];\n  onChange: (ids: string[]) => void;\n}\n\nexport default function ExercisePicker({ selected, onChange }: Props) {\n  const [exercises, setExercises] = useState<Exercise[]>([]);\n  const [search, setSearch] = useState("");\n  const [categoryFilter, setCategoryFilter] = useState<string | null>(null);\n  const [showCustomForm, setShowCustomForm] = useState(false);\n  const [customName, setCustomName] = useState("");\n  const [customDescription, setCustomDescription] = useState("");\n  const [customUnit, setCustomUnit] = useState<"REPS" | "SECONDS">("REPS");\n  const [customCategory, setCustomCategory] = useState("");\n  const [customEquipment, setCustomEquipment] = useState<string[]>([]);\n  const [customImage, setCustomImage] = useState<string | null>(null);\n  const [customVideoUrl, setCustomVideoUrl] = useState("");\n  const fileInputRef = useRef<HTMLInputElement>(null);\n\n  function load() {\n    api.get<Exercise[]>("/exercises").then(setExercises);\n  }\n  useEffect(load, []);\n\n  const filtered = useMemo(\n    () =>\n      exercises.filter(\n        (e) =>\n          e.name.toLowerCase().includes(search.toLowerCase()) && (!categoryFilter || e.category === categoryFilter)\n      ),\n    [exercises, search, categoryFilter]\n  );\n\n  function toggle(id: string) {\n    if (selected.includes(id)) onChange(selected.filter((x) => x !== id));\n    else onChange([...selected, id]);\n  }\n\n  function toggleEquipment(key: string) {\n    setCustomEquipment((prev) => (prev.includes(key) ? prev.filter((k) => k !== key) : [...prev, key]));\n  }\n\n  async function onImageChange(e: React.ChangeEvent<HTMLInputElement>) {\n    const file = e.target.files?.[0];\n    if (!file) return;\n    const dataUrl = await resizeImageFile(file, 400);\n    setCustomImage(dataUrl);\n  }\n\n  async function addCustom() {\n    if (!customName.trim()) return;\n    const created = await api.post<Exercise>("/exercises", {\n      name: customName.trim(),\n      description: customDescription.trim() || undefined,\n      unit: customUnit,\n      category: customCategory || undefined,\n      equipment: customEquipment.length > 0 ? customEquipment : undefined,\n      imageBase64: customImage || undefined,\n      videoUrl: customVideoUrl.trim() || undefined,\n    });\n    setExercises((prev) => [...prev, created]);\n    onChange([...selected, created.id]);\n    setCustomName("");\n    setCustomDescription("");\n    setCustomCategory("");\n    setCustomEquipment([]);\n    setCustomImage(null);\n    setCustomVideoUrl("");\n    setShowCustomForm(false);\n  }\n\n  return (\n    <div>\n      <input\n        placeholder="Rechercher un exercice..."\n        value={search}\n        onChange={(e) => setSearch(e.target.value)}\n        className="w-full bg-surface2 border border-border rounded-md px-3 py-2 mb-2"\n      />\n\n      <div className="flex flex-wrap gap-1.5 mb-3">\n        <button\n          type="button"\n          onClick={() => setCategoryFilter(null)}\n          className={`text-xs px-2.5 py-1 rounded-full border ${\n            !categoryFilter ? "bg-accent/20 border-accent text-text" : "bg-surface2 border-border text-muted"\n          }`}\n        >\n          Tous\n        </button>\n        {CATEGORY_CATALOG.map((c) => (\n          <button\n            type="button"\n            key={c.key}\n            onClick={() => setCategoryFilter(c.key)}\n            className={`text-xs px-2.5 py-1 rounded-full border ${\n              categoryFilter === c.key ? "bg-accent/20 border-accent text-text" : "bg-surface2 border-border text-muted"\n            }`}\n          >\n            {c.label}\n          </button>\n        ))}\n      </div>\n\n      <div className="grid sm:grid-cols-2 gap-2 max-h-72 overflow-y-auto pr-1 mb-3">\n        {filtered.map((exo) => {\n          const isSelected = selected.includes(exo.id);\n          return (\n            <button\n              type="button"\n              key={exo.id}\n              onClick={() => toggle(exo.id)}\n              className={`text-left border rounded-md px-3 py-2 transition-colors ${\n                isSelected ? "bg-accent/15 border-accent text-text" : "bg-surface2 border-border text-muted hover:text-text"\n              }`}\n            >\n              <div className="flex items-center justify-between">\n                <span className="text-sm font-medium">{exo.name}</span>\n                <span className="text-[10px] font-mono uppercase text-muted">\n                  {exo.unit === "REPS" ? "reps" : "sec"}\n                </span>\n              </div>\n              {exo.description && <p className="text-xs text-muted mt-0.5 truncate">{exo.description}</p>}\n            </button>\n          );\n        })}\n      </div>\n\n      {!showCustomForm ? (\n        <button\n          type="button"\n          onClick={() => setShowCustomForm(true)}\n          className="text-sm text-accent hover:text-accentSoft"\n        >\n          + Ajouter un exercice qui n\'est pas dans la liste\n        </button>\n      ) : (\n        <div className="bg-surface2 border border-border rounded-md p-3 space-y-2">\n          <div className="flex flex-wrap gap-2 items-end">\n            <div className="flex-1 min-w-[140px]">\n              <label className="block text-xs text-muted mb-1">Nom de l\'exercice</label>\n              <input\n                value={customName}\n                onChange={(e) => setCustomName(e.target.value)}\n                className="w-full bg-surface border border-border rounded-md px-2 py-1.5 text-sm"\n              />\n            </div>\n            <div>\n              <label className="block text-xs text-muted mb-1">Unite</label>\n              <select\n                value={customUnit}\n                onChange={(e) => setCustomUnit(e.target.value as "REPS" | "SECONDS")}\n                className="bg-surface border border-border rounded-md px-2 py-1.5 text-sm"\n              >\n                <option value="REPS">Répétitions</option>\n                <option value="SECONDS">Secondes (durée tenue)</option>\n              </select>\n            </div>\n          </div>\n\n          <div className="w-full">\n            <label className="block text-xs text-muted mb-1">Description (optionnel)</label>\n            <input\n              value={customDescription}\n              onChange={(e) => setCustomDescription(e.target.value)}\n              placeholder="Ex : bras tendus, dos droit..."\n              className="w-full bg-surface border border-border rounded-md px-2 py-1.5 text-sm"\n            />\n          </div>\n\n          <div>\n            <label className="block text-xs text-muted mb-1">Categorie (optionnel)</label>\n            <select\n              value={customCategory}\n              onChange={(e) => setCustomCategory(e.target.value)}\n              className="w-full bg-surface border border-border rounded-md px-2 py-1.5 text-sm"\n            >\n              <option value="">Non precisee</option>\n              {CATEGORY_CATALOG.map((c) => (\n                <option key={c.key} value={c.key}>\n                  {c.label}\n                </option>\n              ))}\n            </select>\n          </div>\n\n          <div>\n            <label className="block text-xs text-muted mb-1">Materiel necessaire (optionnel)</label>\n            <div className="flex flex-wrap gap-1">\n              {EQUIPMENT_CATALOG.map((eq) => (\n                <button\n                  type="button"\n                  key={eq.key}\n                  onClick={() => toggleEquipment(eq.key)}\n                  className={`text-[11px] px-2 py-1 rounded border ${\n                    customEquipment.includes(eq.key)\n                      ? "bg-accent/20 border-accent text-text"\n                      : "bg-surface border-border text-muted"\n                  }`}\n                >\n                  {eq.label}\n                </button>\n              ))}\n            </div>\n          </div>\n\n          <div className="flex flex-wrap gap-2 items-end">\n            <div>\n              <label className="block text-xs text-muted mb-1">Photo (optionnel)</label>\n              <input ref={fileInputRef} type="file" accept="image/*" onChange={onImageChange} className="hidden" id="exoImage" />\n              <label\n                htmlFor="exoImage"\n                className="inline-block cursor-pointer bg-surface hover:bg-border transition-colors border border-border rounded-md px-2 py-1.5 text-xs"\n              >\n                {customImage ? "Photo ajoutee ✓" : "Choisir une photo"}\n              </label>\n            </div>\n            <div className="flex-1 min-w-[160px]">\n              <label className="block text-xs text-muted mb-1">Lien video (optionnel)</label>\n              <input\n                value={customVideoUrl}\n                onChange={(e) => setCustomVideoUrl(e.target.value)}\n                placeholder="https://youtube.com/..."\n                className="w-full bg-surface border border-border rounded-md px-2 py-1.5 text-xs"\n              />\n            </div>\n          </div>\n\n          <div className="flex gap-2">\n            <button\n              type="button"\n              onClick={addCustom}\n              className="bg-accent text-bg font-semibold rounded-md px-3 py-1.5 text-sm"\n            >\n              Ajouter\n            </button>\n            <button type="button" onClick={() => setShowCustomForm(false)} className="text-muted text-sm px-2">\n              Annuler\n            </button>\n          </div>\n        </div>\n      )}\n    </div>\n  );\n}\n'
FILES['frontend/src/components/ExerciseMediaModal.tsx'] = 'interface Props {\n  name: string;\n  imageBase64: string | null;\n  videoUrl: string | null;\n  onClose: () => void;\n}\n\nexport default function ExerciseMediaModal({ name, imageBase64, videoUrl, onClose }: Props) {\n  return (\n    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4" onClick={onClose}>\n      <div\n        className="bg-surface border border-border rounded-xl p-4 max-w-md w-full max-h-[80vh] overflow-y-auto"\n        onClick={(e) => e.stopPropagation()}\n      >\n        <div className="flex items-center justify-between mb-3">\n          <h3 className="font-display uppercase tracking-wide text-lg">{name}</h3>\n          <button onClick={onClose} className="text-muted hover:text-accent text-xl leading-none">\n            ✕\n          </button>\n        </div>\n        {imageBase64 && <img src={imageBase64} alt={name} className="w-full rounded-md mb-3" />}\n        {videoUrl && (\n          <a\n            href={videoUrl}\n            target="_blank"\n            rel="noopener noreferrer"\n            className="block text-center bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md py-2"\n          >\n            ▶ Voir la video explicative\n          </a>\n        )}\n        {!imageBase64 && !videoUrl && (\n          <p className="text-muted text-sm">Aucune photo ou video disponible pour cet exercice.</p>\n        )}\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/Today.tsx'] = 'import { useEffect, useMemo, useState } from "react";\nimport { Link } from "react-router-dom";\nimport { api } from "../api/client";\nimport DurationInput from "../components/DurationInput";\nimport CircuitRunner from "../components/CircuitRunner";\nimport ExerciseMediaModal from "../components/ExerciseMediaModal";\nimport { secondsToMMSS } from "../lib/duration";\n\ninterface TodayExerciseItem {\n  kind: "exercise";\n  campExerciseId: string;\n  campId: string;\n  campName: string;\n  exerciseId: string;\n  exerciseName: string;\n  description: string | null;\n  unit: "REPS" | "SECONDS";\n  imageBase64: string | null;\n  videoUrl: string | null;\n  targetSets: number;\n  targetMode: "FIXED" | "MAX";\n  targetValue: number | null;\n  personalBest: number | null;\n  done: boolean;\n  log: { setsDone: number; valueDone: number } | null;\n}\n\ninterface TodayCircuitItem {\n  kind: "circuit";\n  campCircuitId: string;\n  campId: string;\n  campName: string;\n  name: string;\n  description: string | null;\n  items: { exerciseId?: string; name: string }[];\n  workSeconds: number;\n  restSeconds: number;\n  rounds: number;\n  roundRestSeconds: number;\n  done: boolean;\n}\n\ninterface NewBadge {\n  key: string;\n  name: string;\n  description: string;\n  emoji: string;\n}\n\n// Repos par defaut entre chaque serie lors d\'un chrono rapide lance sur un seul exercice\nconst QUICK_CHRONO_REST_SECONDS = 15;\n\nfunction targetLabelFor(item: TodayExerciseItem): string {\n  const unitLabel = item.unit === "REPS" ? "reps" : "sec";\n  return item.targetMode === "MAX"\n    ? `${item.targetSets} serie${item.targetSets > 1 ? "s" : ""} à fond${\n        item.personalBest\n          ? ` (record : ${item.unit === "SECONDS" ? secondsToMMSS(item.personalBest) : item.personalBest} ${unitLabel})`\n          : ""\n      }`\n    : `${item.targetSets} x ${\n        item.unit === "SECONDS" && item.targetValue ? secondsToMMSS(item.targetValue) : item.targetValue\n      } ${item.unit === "SECONDS" ? "" : unitLabel}`;\n}\n\nexport default function Today() {\n  const [items, setItems] = useState<TodayExerciseItem[] | null>(null);\n  const [circuits, setCircuits] = useState<TodayCircuitItem[]>([]);\n  const [editingId, setEditingId] = useState<string | null>(null); // campExerciseId (simple) ou exerciseId (groupe)\n  const [selectedCampIds, setSelectedCampIds] = useState<string[]>([]);\n  const [sets, setSets] = useState(0);\n  const [value, setValue] = useState(0);\n  const [celebrating, setCelebrating] = useState<NewBadge[]>([]);\n  const [isRestToday, setIsRestToday] = useState(false);\n  const [restBusy, setRestBusy] = useState(false);\n  const [viewingMedia, setViewingMedia] = useState<TodayExerciseItem | null>(null);\n  const [runner, setRunner] = useState<\n    | { type: "exercise"; item: TodayExerciseItem }\n    | { type: "circuit"; item: TodayCircuitItem }\n    | null\n  >(null);\n\n  function load() {\n    api\n      .get<{ date: string; items: TodayExerciseItem[]; circuits: TodayCircuitItem[] }>("/today")\n      .then((res) => {\n        setItems(res.items);\n        setCircuits(res.circuits);\n      });\n  }\n  useEffect(load, []);\n\n  useEffect(() => {\n    const todayKey = new Date().toISOString().slice(0, 10);\n    api.get<{ date: string }[]>("/rest-days").then((days) => {\n      setIsRestToday(days.some((d) => d.date.slice(0, 10) === todayKey));\n    });\n  }, []);\n\n  async function toggleRestDay() {\n    setRestBusy(true);\n    try {\n      if (isRestToday) {\n        await api.del("/rest-days");\n        setIsRestToday(false);\n      } else {\n        await api.post("/rest-days", {});\n        setIsRestToday(true);\n      }\n    } finally {\n      setRestBusy(false);\n    }\n  }\n\n  // Regroupe les exercices identiques (meme exerciseId) presents dans plusieurs camps,\n  // pour proposer une validation combinee plutot que deux cartes separees.\n  const groups = useMemo(() => {\n    const map = new Map<string, TodayExerciseItem[]>();\n    items?.forEach((item) => {\n      const arr = map.get(item.exerciseId) ?? [];\n      arr.push(item);\n      map.set(item.exerciseId, arr);\n    });\n    return [...map.values()];\n  }, [items]);\n\n  function startEditingSingle(item: TodayExerciseItem) {\n    setEditingId(item.campExerciseId);\n    setSelectedCampIds([item.campId]);\n    setSets(item.log?.setsDone ?? item.targetSets);\n    setValue(item.log?.valueDone ?? item.targetValue ?? item.personalBest ?? 0);\n  }\n\n  function startEditingGroup(group: TodayExerciseItem[]) {\n    const notDone = group.filter((i) => !i.done);\n    setEditingId(group[0].exerciseId);\n    setSelectedCampIds(notDone.map((i) => i.campId));\n    const ref = notDone[0] ?? group[0];\n    setSets(ref.targetSets);\n    setValue(ref.targetValue ?? ref.personalBest ?? 0);\n  }\n\n  async function confirmCampIds(exerciseId: string, campIds: string[]) {\n    if (campIds.length === 0) {\n      setEditingId(null);\n      return;\n    }\n    const res = await api.post<{ newBadges: NewBadge[] }>("/logs", {\n      campIds,\n      exerciseId,\n      setsDone: sets,\n      valueDone: value,\n    });\n    setEditingId(null);\n    load();\n    if (res.newBadges?.length) setCelebrating(res.newBadges);\n  }\n\n  async function undo(item: TodayExerciseItem) {\n    await api.del(`/logs?campId=${item.campId}&exerciseId=${item.exerciseId}`);\n    load();\n  }\n\n  async function onExerciseChronoComplete(item: TodayExerciseItem) {\n    const res = await api.post<{ newBadges: NewBadge[] }>("/logs", {\n      campId: item.campId,\n      exerciseId: item.exerciseId,\n      setsDone: item.targetSets,\n      valueDone: item.targetValue ?? 0,\n    });\n    setRunner(null);\n    load();\n    if (res.newBadges?.length) setCelebrating(res.newBadges);\n  }\n\n  async function onCircuitComplete(item: TodayCircuitItem, totalDurationSeconds: number) {\n    const res = await api.post<{ newBadges: NewBadge[] }>(`/camp-circuits/${item.campCircuitId}/log`, {\n      durationSeconds: totalDurationSeconds,\n    });\n    setRunner(null);\n    load();\n    if (res.newBadges?.length) setCelebrating(res.newBadges);\n  }\n\n  if (runner?.type === "exercise") {\n    const item = runner.item;\n    return (\n      <div className="max-w-md mx-auto">\n        <CircuitRunner\n          items={[{ name: item.exerciseName }]}\n          workSeconds={item.targetValue ?? 30}\n          restSeconds={0}\n          rounds={item.targetSets}\n          roundRestSeconds={QUICK_CHRONO_REST_SECONDS}\n          onComplete={() => onExerciseChronoComplete(item)}\n          onCancel={() => setRunner(null)}\n        />\n      </div>\n    );\n  }\n\n  if (runner?.type === "circuit") {\n    const item = runner.item;\n    return (\n      <div className="max-w-md mx-auto">\n        <CircuitRunner\n          items={item.items.map((i) => ({ name: i.name }))}\n          workSeconds={item.workSeconds}\n          restSeconds={item.restSeconds}\n          rounds={item.rounds}\n          roundRestSeconds={item.roundRestSeconds}\n          onComplete={(duration) => onCircuitComplete(item, duration)}\n          onCancel={() => setRunner(null)}\n        />\n      </div>\n    );\n  }\n\n  const doneCount = (items?.filter((i) => i.done).length ?? 0) + circuits.filter((c) => c.done).length;\n  const total = (items?.length ?? 0) + circuits.length;\n\n  return (\n    <div className="max-w-xl">\n      {viewingMedia && (\n        <ExerciseMediaModal\n          name={viewingMedia.exerciseName}\n          imageBase64={viewingMedia.imageBase64}\n          videoUrl={viewingMedia.videoUrl}\n          onClose={() => setViewingMedia(null)}\n        />\n      )}\n\n      {celebrating.length > 0 && (\n        <div className="bg-accent/10 border border-accent rounded-xl p-4 mb-5">\n          {celebrating.map((b) => (\n            <p key={b.key} className="text-sm">\n              <span className="text-xl mr-2">{b.emoji}</span>\n              Nouveau badge : <span className="font-semibold">{b.name}</span> — {b.description}\n            </p>\n          ))}\n          <button onClick={() => setCelebrating([])} className="text-xs text-muted hover:text-text mt-2">\n            Fermer\n          </button>\n        </div>\n      )}\n\n      <h1 className="font-display text-3xl uppercase tracking-wide mb-1">Aujourd\'hui</h1>\n      <p className="text-muted text-sm mb-3">\n        {total === 0\n          ? "Rien de prevu aujourd\'hui."\n          : `${doneCount} / ${total} séance${total > 1 ? "s" : ""} validee${doneCount > 1 ? "s" : ""}.`}\n      </p>\n\n      {isRestToday ? (\n        <div className="bg-success/10 border border-success rounded-xl p-3 mb-5 flex items-center justify-between gap-3">\n          <p className="text-sm">😴 Jour de repos justifie — ta serie de régularité n\'est pas cassee aujourd\'hui.</p>\n          <button\n            onClick={toggleRestDay}\n            disabled={restBusy}\n            className="text-xs text-muted hover:text-accent shrink-0"\n          >\n            Annuler\n          </button>\n        </div>\n      ) : (\n        <button\n          onClick={toggleRestDay}\n          disabled={restBusy}\n          className="text-xs text-muted hover:text-accent mb-5 underline decoration-dotted"\n        >\n          😴 Marquer aujourd\'hui comme jour de repos (blessure, voyage...)\n        </button>\n      )}\n\n      {items === null && <p className="text-muted">Chargement...</p>}\n\n      {items?.length === 0 && circuits.length === 0 && (\n        <div className="bg-surface border border-dashed border-border rounded-xl p-8 text-center">\n          <p className="text-muted text-sm mb-3">\n            Aucun exercice programmé pour aujourd\'hui. Va voir tes camps pour rejoindre ou créer un camp.\n          </p>\n          <Link to="/camps" className="text-accent hover:text-accentSoft text-sm">\n            Voir mes camps\n          </Link>\n        </div>\n      )}\n\n      {circuits.length > 0 && (\n        <div className="space-y-3 mb-4">\n          {circuits.map((c) => (\n            <div\n              key={c.campCircuitId}\n              className={`bg-surface border rounded-xl p-4 ${c.done ? "border-success/50" : "border-border"}`}\n            >\n              <div className="flex items-center justify-between gap-3 flex-wrap">\n                <div>\n                  <p className="font-medium">🔁 {c.name}</p>\n                  <p className="text-xs text-muted">\n                    {c.campName} · {c.rounds} tour{c.rounds > 1 ? "s" : ""} · {c.items.length} exercice\n                    {c.items.length > 1 ? "s" : ""}\n                  </p>\n                  {c.description && <p className="text-xs text-muted italic mt-0.5">"{c.description}"</p>}\n                </div>\n                {c.done ? (\n                  <span className="text-success text-sm shrink-0">✓ Fait</span>\n                ) : (\n                  <button\n                    onClick={() => setRunner({ type: "circuit", item: c })}\n                    className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-4 py-2 text-sm shrink-0"\n                  >\n                    ⏱ Lancer\n                  </button>\n                )}\n              </div>\n            </div>\n          ))}\n        </div>\n      )}\n\n      <div className="space-y-3">\n        {groups.map((group) => {\n          const first = group[0];\n          const isGrouped = group.length > 1;\n          const unitLabel = first.unit === "REPS" ? "reps" : "sec";\n          const hasMedia = !!(first.imageBase64 || first.videoUrl);\n          const allDone = group.every((i) => i.done);\n          const isEditing = editingId === (isGrouped ? first.exerciseId : first.campExerciseId);\n          const canQuickChrono = !isGrouped && first.unit === "SECONDS" && first.targetMode === "FIXED" && !first.done;\n\n          return (\n            <div\n              key={first.exerciseId}\n              className={`bg-surface border rounded-xl p-4 transition-colors ${\n                allDone ? "border-success/50" : "border-border"\n              }`}\n            >\n              <div className="flex items-center justify-between gap-3 flex-wrap">\n                <div>\n                  <button\n                    onClick={() => hasMedia && setViewingMedia(first)}\n                    className={`font-medium text-left ${hasMedia ? "underline decoration-dotted hover:text-accent" : ""}`}\n                    title={hasMedia ? "Voir la photo/video de l\'exercice" : undefined}\n                  >\n                    {first.exerciseName} {hasMedia && "📷"}\n                  </button>\n                  {!isGrouped ? (\n                    <p className="text-xs text-muted">\n                      {first.campName} · objectif {targetLabelFor(first)}\n                    </p>\n                  ) : (\n                    <div className="text-xs text-muted space-y-0.5">\n                      {group.map((i) => (\n                        <p key={i.campId}>\n                          {i.done ? "✓ " : ""}\n                          {i.campName} · {targetLabelFor(i)}\n                        </p>\n                      ))}\n                    </div>\n                  )}\n                  {first.description && <p className="text-xs text-muted italic mt-0.5">"{first.description}"</p>}\n                </div>\n\n                {!isEditing && (\n                  <div className="flex items-center gap-2 shrink-0">\n                    {canQuickChrono && (\n                      <button\n                        onClick={() => setRunner({ type: "exercise", item: first })}\n                        title="Lancer le chrono pour cet exercice"\n                        className="w-10 h-10 rounded-full flex items-center justify-center border-2 border-accent text-accent hover:bg-accent/10"\n                      >\n                        ⏱\n                      </button>\n                    )}\n                    {allDone ? (\n                      <button\n                        onClick={() => undo(first)}\n                        className="stamp-btn w-12 h-12 rounded-full flex items-center justify-center text-lg font-bold border-2 bg-success/20 border-success text-success"\n                        title="Fait - clique pour annuler"\n                      >\n                        ✓\n                      </button>\n                    ) : (\n                      <button\n                        onClick={() => (isGrouped ? startEditingGroup(group) : startEditingSingle(first))}\n                        className="stamp-btn w-12 h-12 rounded-full flex items-center justify-center text-lg font-bold border-2 bg-surface2 border-border text-muted hover:border-accent hover:text-accent"\n                        title="Marquer comme fait"\n                      />\n                    )}\n                  </div>\n                )}\n              </div>\n\n              {!isGrouped && first.done && first.log && (\n                <p className="text-xs text-muted mt-2">\n                  Réalisé : {first.log.setsDone} x{" "}\n                  {first.unit === "SECONDS" ? secondsToMMSS(first.log.valueDone) : `${first.log.valueDone} ${unitLabel}`}\n                </p>\n              )}\n\n              {isEditing && (\n                <div className="mt-3 bg-surface2 border border-border rounded-md p-3 space-y-3">\n                  {isGrouped && (\n                    <div>\n                      <p className="text-xs text-muted mb-1">Valider pour :</p>\n                      <div className="flex flex-wrap gap-2">\n                        {group\n                          .filter((i) => !i.done)\n                          .map((i) => (\n                            <label key={i.campId} className="flex items-center gap-1.5 text-sm">\n                              <input\n                                type="checkbox"\n                                checked={selectedCampIds.includes(i.campId)}\n                                onChange={(e) =>\n                                  setSelectedCampIds((prev) =>\n                                    e.target.checked ? [...prev, i.campId] : prev.filter((c) => c !== i.campId)\n                                  )\n                                }\n                              />\n                              {i.campName}\n                            </label>\n                          ))}\n                      </div>\n                    </div>\n                  )}\n                  <div className="flex items-end gap-3 flex-wrap">\n                    <div>\n                      <label className="block text-xs text-muted mb-1">Series faites</label>\n                      <input\n                        type="number"\n                        min={0}\n                        value={sets}\n                        onChange={(e) => setSets(Number(e.target.value))}\n                        className="w-20 bg-surface border border-border rounded-md px-2 py-1"\n                      />\n                    </div>\n                    <div>\n                      <label className="block text-xs text-muted mb-1">{unitLabel} par serie</label>\n                      {first.unit === "SECONDS" ? (\n                        <DurationInput totalSeconds={value} onChange={setValue} />\n                      ) : (\n                        <input\n                          type="number"\n                          min={0}\n                          value={value}\n                          onChange={(e) => setValue(Number(e.target.value))}\n                          className="w-20 bg-surface border border-border rounded-md px-2 py-1"\n                        />\n                      )}\n                    </div>\n                    <button\n                      onClick={() => confirmCampIds(first.exerciseId, selectedCampIds)}\n                      className="bg-accent text-bg font-semibold rounded-md px-4 py-1.5 text-sm"\n                    >\n                      Valider\n                    </button>\n                    <button onClick={() => setEditingId(null)} className="text-muted text-sm px-2">\n                      Annuler\n                    </button>\n                  </div>\n                </div>\n              )}\n            </div>\n          );\n        })}\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/Chrono.tsx'] = 'import { useEffect, useMemo, useRef, useState } from "react";\nimport { api } from "../api/client";\nimport CircuitRunner from "../components/CircuitRunner";\n\ninterface CatalogExercise {\n  id: string;\n  name: string;\n  unit: "REPS" | "SECONDS";\n}\n\ninterface CircuitItem {\n  key: string;\n  name: string;\n}\n\ninterface NewBadge {\n  key: string;\n  name: string;\n  description: string;\n  emoji: string;\n}\n\ninterface FavoriteCircuit {\n  id: string;\n  name: string;\n  items: string; // JSON\n  workSeconds: number;\n  restSeconds: number;\n  rounds: number;\n  roundRestSeconds: number;\n}\n\nexport default function Chrono() {\n  const [mode, setMode] = useState<"circuit" | "minuteur" | "chronometre">("circuit");\n\n  const [catalog, setCatalog] = useState<CatalogExercise[]>([]);\n  const [search, setSearch] = useState("");\n  const [items, setItems] = useState<CircuitItem[]>([]);\n  const [customName, setCustomName] = useState("");\n\n  const [workSeconds, setWorkSeconds] = useState(40);\n  const [restSeconds, setRestSeconds] = useState(20);\n  const [rounds, setRounds] = useState(3);\n  const [roundRestSeconds, setRoundRestSeconds] = useState(60);\n\n  const [isRunningCircuit, setIsRunningCircuit] = useState(false);\n  const [celebrating, setCelebrating] = useState<NewBadge[]>([]);\n\n  const [favorites, setFavorites] = useState<FavoriteCircuit[]>([]);\n  const [savingFavoriteName, setSavingFavoriteName] = useState<string | null>(null);\n\n  useEffect(() => {\n    api.get<CatalogExercise[]>("/exercises").then(setCatalog);\n    loadFavorites();\n  }, []);\n\n  function loadFavorites() {\n    api.get<FavoriteCircuit[]>("/favorite-circuits").then(setFavorites);\n  }\n\n  function loadFavorite(fav: FavoriteCircuit) {\n    const names = JSON.parse(fav.items) as string[];\n    setItems(names.map((name) => ({ key: `${name}-${Date.now()}-${Math.random()}`, name })));\n    setWorkSeconds(fav.workSeconds);\n    setRestSeconds(fav.restSeconds);\n    setRounds(fav.rounds);\n    setRoundRestSeconds(fav.roundRestSeconds);\n  }\n\n  async function saveFavorite() {\n    if (!savingFavoriteName?.trim() || items.length === 0) return;\n    await api.post("/favorite-circuits", {\n      name: savingFavoriteName.trim(),\n      items: items.map((i) => i.name),\n      workSeconds,\n      restSeconds,\n      rounds,\n      roundRestSeconds,\n    });\n    setSavingFavoriteName(null);\n    loadFavorites();\n  }\n\n  async function deleteFavorite(id: string) {\n    await api.del(`/favorite-circuits/${id}`);\n    loadFavorites();\n  }\n\n  const filteredCatalog = useMemo(\n    () => catalog.filter((e) => e.name.toLowerCase().includes(search.toLowerCase())),\n    [catalog, search]\n  );\n\n  function addItem(name: string) {\n    setItems((prev) => [...prev, { key: `${name}-${Date.now()}-${Math.random()}`, name }]);\n  }\n\n  async function addCustom() {\n    if (!customName.trim()) return;\n    try {\n      const created = await api.post<CatalogExercise>("/exercises", { name: customName.trim(), unit: "REPS" });\n      setCatalog((prev) => [...prev, created]);\n      addItem(created.name);\n    } catch {\n      addItem(customName.trim());\n    }\n    setCustomName("");\n  }\n\n  function removeItem(key: string) {\n    setItems((prev) => prev.filter((i) => i.key !== key));\n  }\n\n  function moveItem(key: string, direction: -1 | 1) {\n    setItems((prev) => {\n      const index = prev.findIndex((i) => i.key === key);\n      const newIndex = index + direction;\n      if (newIndex < 0 || newIndex >= prev.length) return prev;\n      const copy = [...prev];\n      [copy[index], copy[newIndex]] = [copy[newIndex], copy[index]];\n      return copy;\n    });\n  }\n\n  async function onCircuitComplete(totalDurationSeconds: number) {\n    setIsRunningCircuit(false);\n    try {\n      const res = await api.post<{ newBadges: NewBadge[] }>("/chrono-sessions", {\n        items: items.map((i) => i.name),\n        workSeconds,\n        restSeconds,\n        rounds,\n        roundRestSeconds,\n        totalDurationSeconds,\n      });\n      if (res.newBadges?.length) setCelebrating(res.newBadges);\n    } catch {\n      // même si l\'enregistrement echoue (ex: hors ligne), on ne bloque pas l\'utilisateur\n    }\n  }\n\n  if (isRunningCircuit) {\n    return (\n      <div className="max-w-md mx-auto">\n        <CircuitRunner\n          items={items.map((i) => ({ name: i.name }))}\n          workSeconds={workSeconds}\n          restSeconds={restSeconds}\n          rounds={rounds}\n          roundRestSeconds={roundRestSeconds}\n          onComplete={onCircuitComplete}\n          onCancel={() => setIsRunningCircuit(false)}\n        />\n      </div>\n    );\n  }\n\n  return (\n    <div className="max-w-2xl">\n      {celebrating.length > 0 && (\n        <div className="bg-accent/10 border border-accent rounded-xl p-4 mb-5">\n          {celebrating.map((b) => (\n            <p key={b.key} className="text-sm">\n              <span className="text-xl mr-2">{b.emoji}</span>\n              Nouveau badge : <span className="font-semibold">{b.name}</span> — {b.description}\n            </p>\n          ))}\n          <button onClick={() => setCelebrating([])} className="text-xs text-muted hover:text-text mt-2">\n            Fermer\n          </button>\n        </div>\n      )}\n\n      <h1 className="font-display text-3xl uppercase tracking-wide mb-1">Chronometre</h1>\n      <p className="text-muted text-sm mb-4">\n        Construis ta propre séance en circuit training, ou utilise simplement un minuteur ou un chronometre.\n      </p>\n\n      <div className="flex gap-1.5 mb-6 flex-wrap">\n        <button\n          onClick={() => setMode("circuit")}\n          className={`px-3 py-1.5 rounded text-sm border ${\n            mode === "circuit" ? "bg-accent/20 border-accent text-text" : "bg-surface border-border text-muted"\n          }`}\n        >\n          Circuit training\n        </button>\n        <button\n          onClick={() => setMode("minuteur")}\n          className={`px-3 py-1.5 rounded text-sm border ${\n            mode === "minuteur" ? "bg-accent/20 border-accent text-text" : "bg-surface border-border text-muted"\n          }`}\n        >\n          Minuteur\n        </button>\n        <button\n          onClick={() => setMode("chronometre")}\n          className={`px-3 py-1.5 rounded text-sm border ${\n            mode === "chronometre" ? "bg-accent/20 border-accent text-text" : "bg-surface border-border text-muted"\n          }`}\n        >\n          Chronometre\n        </button>\n      </div>\n\n      {mode === "minuteur" ? (\n        <MinuteurTimer />\n      ) : mode === "chronometre" ? (\n        <ChronometreTimer />\n      ) : (\n        <div className="grid md:grid-cols-2 gap-6">\n          <div>\n            {favorites.length > 0 && (\n              <div className="mb-5">\n                <h2 className="font-display uppercase tracking-wide text-sm mb-2">Mes circuits favoris</h2>\n                <div className="space-y-1.5">\n                  {favorites.map((fav) => (\n                    <div\n                      key={fav.id}\n                      className="flex items-center justify-between bg-surface border border-border rounded-md px-3 py-2 text-sm"\n                    >\n                      <button onClick={() => loadFavorite(fav)} className="text-left hover:text-accent">\n                        ⭐ {fav.name}\n                      </button>\n                      <button onClick={() => deleteFavorite(fav.id)} className="text-muted hover:text-accent text-xs">\n                        ✕\n                      </button>\n                    </div>\n                  ))}\n                </div>\n              </div>\n            )}\n\n            <h2 className="font-display uppercase tracking-wide text-sm mb-2">1. Choisis tes exercices</h2>\n            <input\n              placeholder="Rechercher un exercice..."\n              value={search}\n              onChange={(e) => setSearch(e.target.value)}\n              className="w-full bg-surface2 border border-border rounded-md px-3 py-2 mb-2 text-sm"\n            />\n            <div className="grid grid-cols-2 gap-1.5 max-h-40 overflow-y-auto mb-2">\n              {filteredCatalog.map((exo) => (\n                <button\n                  key={exo.id}\n                  type="button"\n                  onClick={() => addItem(exo.name)}\n                  className="text-left text-sm bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-2 py-1.5"\n                >\n                  + {exo.name}\n                </button>\n              ))}\n            </div>\n            <div className="flex gap-2">\n              <input\n                value={customName}\n                onChange={(e) => setCustomName(e.target.value)}\n                placeholder="Nouvel exercice..."\n                className="flex-1 bg-surface2 border border-border rounded-md px-2 py-1.5 text-sm"\n              />\n              <button\n                type="button"\n                onClick={addCustom}\n                className="bg-accent text-bg font-semibold rounded-md px-3 py-1.5 text-sm"\n              >\n                Ajouter\n              </button>\n            </div>\n\n            <h3 className="font-display uppercase tracking-wide text-xs mt-4 mb-2 text-muted">\n              Circuit ({items.length} exercice{items.length > 1 ? "s" : ""})\n            </h3>\n            <div className="space-y-1.5">\n              {items.length === 0 && <p className="text-muted text-sm italic">Aucun exercice ajouté pour l\'instant.</p>}\n              {items.map((item, index) => (\n                <div\n                  key={item.key}\n                  className="flex items-center justify-between bg-surface border border-border rounded-md px-3 py-1.5 text-sm"\n                >\n                  <span>\n                    {index + 1}. {item.name}\n                  </span>\n                  <div className="flex gap-1 items-center">\n                    <button onClick={() => moveItem(item.key, -1)} className="text-muted hover:text-text px-1">\n                      ↑\n                    </button>\n                    <button onClick={() => moveItem(item.key, 1)} className="text-muted hover:text-text px-1">\n                      ↓\n                    </button>\n                    <button onClick={() => removeItem(item.key)} className="text-muted hover:text-accent px-1">\n                      ✕\n                    </button>\n                  </div>\n                </div>\n              ))}\n            </div>\n          </div>\n\n          <div>\n            <h2 className="font-display uppercase tracking-wide text-sm mb-2">2. Réglages du circuit</h2>\n            <div className="bg-surface border border-border rounded-lg p-4 space-y-3">\n              <div>\n                <label className="block text-xs text-muted mb-1">Temps de travail (secondes)</label>\n                <input\n                  type="number"\n                  min={5}\n                  value={workSeconds}\n                  onChange={(e) => setWorkSeconds(Number(e.target.value))}\n                  className="w-full bg-surface2 border border-border rounded-md px-2 py-1.5 text-sm"\n                />\n              </div>\n              <div>\n                <label className="block text-xs text-muted mb-1">Temps de repos entre exercices (secondes)</label>\n                <input\n                  type="number"\n                  min={0}\n                  value={restSeconds}\n                  onChange={(e) => setRestSeconds(Number(e.target.value))}\n                  className="w-full bg-surface2 border border-border rounded-md px-2 py-1.5 text-sm"\n                />\n              </div>\n              <div>\n                <label className="block text-xs text-muted mb-1">Nombre de tours</label>\n                <input\n                  type="number"\n                  min={1}\n                  value={rounds}\n                  onChange={(e) => setRounds(Number(e.target.value))}\n                  className="w-full bg-surface2 border border-border rounded-md px-2 py-1.5 text-sm"\n                />\n              </div>\n              <div>\n                <label className="block text-xs text-muted mb-1">Repos entre chaque tour (secondes)</label>\n                <input\n                  type="number"\n                  min={0}\n                  value={roundRestSeconds}\n                  onChange={(e) => setRoundRestSeconds(Number(e.target.value))}\n                  className="w-full bg-surface2 border border-border rounded-md px-2 py-1.5 text-sm"\n                />\n              </div>\n            </div>\n\n            <button\n              onClick={() => setIsRunningCircuit(true)}\n              disabled={items.length === 0}\n              className="w-full mt-4 bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md py-2.5 disabled:opacity-50"\n            >\n              Lancer le circuit\n            </button>\n\n            {savingFavoriteName !== null ? (\n              <div className="flex gap-2 mt-2">\n                <input\n                  value={savingFavoriteName}\n                  onChange={(e) => setSavingFavoriteName(e.target.value)}\n                  placeholder="Nom du circuit favori..."\n                  className="flex-1 bg-surface2 border border-border rounded-md px-2 py-1.5 text-sm"\n                />\n                <button onClick={saveFavorite} className="bg-surface2 hover:bg-border border border-border rounded-md px-3 py-1.5 text-sm">\n                  OK\n                </button>\n                <button onClick={() => setSavingFavoriteName(null)} className="text-muted text-sm px-2">\n                  ✕\n                </button>\n              </div>\n            ) : (\n              <button\n                onClick={() => setSavingFavoriteName("")}\n                disabled={items.length === 0}\n                className="w-full mt-2 text-sm text-accent hover:text-accentSoft disabled:opacity-40"\n              >\n                ⭐ Sauvegarder ce circuit en favori\n              </button>\n            )}\n          </div>\n        </div>\n      )}\n    </div>\n  );\n}\n\nfunction beepShort() {\n  try {\n    const AudioCtx = window.AudioContext || (window as any).webkitAudioContext;\n    const ctx = new AudioCtx();\n    const osc = ctx.createOscillator();\n    osc.frequency.value = 660;\n    osc.connect(ctx.destination);\n    osc.start();\n    osc.stop(ctx.currentTime + 0.4);\n    osc.onended = () => ctx.close();\n  } catch {\n    /* pas grave si pas de son */\n  }\n}\n\n// Minuteur : compte a rebours simple depuis une durée choisie, avec bip a la fin.\nfunction MinuteurTimer() {\n  const [inputMinutes, setInputMinutes] = useState(1);\n  const [inputSeconds, setInputSeconds] = useState(0);\n  const [remaining, setRemaining] = useState(60);\n  const [running, setRunning] = useState(false);\n  const intervalRef = useRef<number | null>(null);\n\n  function applySettings() {\n    setRemaining(inputMinutes * 60 + inputSeconds);\n    setRunning(false);\n  }\n\n  useEffect(() => {\n    if (!running) return;\n    intervalRef.current = window.setInterval(() => {\n      setRemaining((r) => {\n        if (r <= 1) {\n          setRunning(false);\n          beepShort();\n          return 0;\n        }\n        return r - 1;\n      });\n    }, 1000);\n    return () => {\n      if (intervalRef.current) window.clearInterval(intervalRef.current);\n    };\n  }, [running]);\n\n  const mm = Math.floor(remaining / 60);\n  const ss = remaining % 60;\n\n  return (\n    <div className="max-w-sm mx-auto text-center">\n      <div className="border-4 border-accent rounded-full w-56 h-56 mx-auto flex flex-col items-center justify-center my-6">\n        <p className="font-display text-6xl">\n          {mm}:{ss.toString().padStart(2, "0")}\n        </p>\n      </div>\n\n      <div className="flex justify-center gap-3 mb-6">\n        <button\n          onClick={() => setRunning((r) => !r)}\n          disabled={remaining === 0}\n          className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-5 py-2 disabled:opacity-50"\n        >\n          {running ? "Pause" : "Demarrer"}\n        </button>\n        <button\n          onClick={applySettings}\n          className="bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-4 py-2 text-sm"\n        >\n          Réinitialiser\n        </button>\n      </div>\n\n      <div className="bg-surface border border-border rounded-lg p-4">\n        <p className="text-xs text-muted mb-2">Regle la durée du compte a rebours.</p>\n        <div className="flex items-center justify-center gap-2">\n          <input\n            type="number"\n            min={0}\n            value={inputMinutes}\n            onChange={(e) => setInputMinutes(Number(e.target.value))}\n            className="w-16 bg-surface2 border border-border rounded-md px-2 py-1.5 text-sm text-center"\n          />\n          <span className="text-muted text-sm">min</span>\n          <input\n            type="number"\n            min={0}\n            max={59}\n            value={inputSeconds}\n            onChange={(e) => setInputSeconds(Number(e.target.value))}\n            className="w-16 bg-surface2 border border-border rounded-md px-2 py-1.5 text-sm text-center"\n          />\n          <span className="text-muted text-sm">sec</span>\n          <button\n            onClick={applySettings}\n            className="bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-3 py-1.5 text-sm"\n          >\n            Appliquer\n          </button>\n        </div>\n      </div>\n    </div>\n  );\n}\n\n// Chronometre : compte en avant depuis 0, comme un vrai chronometre de sport.\nfunction ChronometreTimer() {\n  const [elapsed, setElapsed] = useState(0);\n  const [running, setRunning] = useState(false);\n  const intervalRef = useRef<number | null>(null);\n\n  useEffect(() => {\n    if (!running) return;\n    intervalRef.current = window.setInterval(() => setElapsed((e) => e + 1), 1000);\n    return () => {\n      if (intervalRef.current) window.clearInterval(intervalRef.current);\n    };\n  }, [running]);\n\n  const mm = Math.floor(elapsed / 60);\n  const ss = elapsed % 60;\n\n  return (\n    <div className="max-w-sm mx-auto text-center">\n      <div className="border-4 border-accent rounded-full w-56 h-56 mx-auto flex flex-col items-center justify-center my-6">\n        <p className="font-display text-6xl">\n          {mm}:{ss.toString().padStart(2, "0")}\n        </p>\n      </div>\n\n      <div className="flex justify-center gap-3">\n        <button\n          onClick={() => setRunning((r) => !r)}\n          className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-5 py-2"\n        >\n          {running ? "Pause" : elapsed === 0 ? "Demarrer" : "Reprendre"}\n        </button>\n        <button\n          onClick={() => {\n            setRunning(false);\n            setElapsed(0);\n          }}\n          className="bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-4 py-2 text-sm"\n        >\n          Réinitialiser\n        </button>\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/Profile.tsx'] = 'import { FormEvent, useEffect, useRef, useState } from "react";\nimport { Link, useNavigate } from "react-router-dom";\nimport { useAuth } from "../context/AuthContext";\nimport { api, ApiError } from "../api/client";\nimport { enablePushNotifications } from "../lib/push";\nimport { resizeImageFile } from "../lib/image";\nimport { SPORTS_LIST, SPORT_LEVELS } from "../lib/sports";\nimport { EQUIPMENT_CATALOG } from "../lib/equipment";\n\ninterface Badge {\n  key: string;\n  name: string;\n  description: string;\n  emoji: string;\n  earned: boolean;\n  earnedAt: string | null;\n}\n\ninterface CampSummary {\n  id: string;\n  name: string;\n  description: string | null;\n  role: "COACH" | "PLAYER";\n  memberCount: number;\n  exercises: string[];\n}\n\nexport default function Profile() {\n  const { user, refreshUser, logout } = useAuth();\n  const navigate = useNavigate();\n  const [weightKg, setWeightKg] = useState(user?.weightKg?.toString() ?? "");\n  const [heightCm, setHeightCm] = useState(user?.heightCm?.toString() ?? "");\n  const [birthDate, setBirthDate] = useState(user?.birthDate?.slice(0, 10) ?? "");\n  const [sex, setSex] = useState(user?.sex ?? "");\n  const [sport, setSport] = useState(user?.sport ?? "");\n  const [sportLevel, setSportLevel] = useState(user?.sportLevel ?? "");\n  const [location, setLocation] = useState(user?.location ?? "");\n  const [equipment, setEquipment] = useState<string[]>(user?.equipment ? JSON.parse(user.equipment) : []);\n  const [message, setMessage] = useState<string | null>(null);\n  const [error, setError] = useState<string | null>(null);\n  const [busy, setBusy] = useState(false);\n  const [badges, setBadges] = useState<Badge[] | null>(null);\n  const [avatarUploading, setAvatarUploading] = useState(false);\n  const fileInputRef = useRef<HTMLInputElement>(null);\n  const [summary, setSummary] = useState<{ overallRegularityRate: number | null; camps: CampSummary[] } | null>(null);\n\n  useEffect(() => {\n    api.get<Badge[]>("/badges").then(setBadges);\n    api.get<{ overallRegularityRate: number | null; camps: CampSummary[] }>("/users/me/summary").then(setSummary);\n  }, []);\n\n  function toggleEquipment(key: string) {\n    setEquipment((prev) => (prev.includes(key) ? prev.filter((k) => k !== key) : [...prev, key]));\n  }\n\n  async function onSubmit(e: FormEvent) {\n    e.preventDefault();\n    setError(null);\n    setMessage(null);\n    setBusy(true);\n    try {\n      await api.put("/users/me", {\n        weightKg: weightKg ? Number(weightKg) : null,\n        heightCm: heightCm ? Number(heightCm) : null,\n        birthDate: birthDate || null,\n        sex: sex || null,\n        sport: sport || null,\n        sportLevel: sportLevel || null,\n        location: location.trim() || null,\n        equipment: equipment.length > 0 ? equipment : null,\n      });\n      await refreshUser();\n      setMessage("Profil mis à jour.");\n    } catch (err) {\n      setError(err instanceof ApiError ? err.message : "Impossible de mettre à jour le profil.");\n    } finally {\n      setBusy(false);\n    }\n  }\n\n  async function onAvatarChange(e: React.ChangeEvent<HTMLInputElement>) {\n    const file = e.target.files?.[0];\n    if (!file) return;\n    setAvatarUploading(true);\n    setError(null);\n    try {\n      const dataUrl = await resizeImageFile(file);\n      await api.put("/users/me", { avatarBase64: dataUrl });\n      await refreshUser();\n    } catch {\n      setError("Impossible de mettre à jour la photo de profil.");\n    } finally {\n      setAvatarUploading(false);\n      if (fileInputRef.current) fileInputRef.current.value = "";\n    }\n  }\n\n  async function removeAvatar() {\n    setAvatarUploading(true);\n    try {\n      await api.put("/users/me", { avatarBase64: null });\n      await refreshUser();\n    } finally {\n      setAvatarUploading(false);\n    }\n  }\n\n  async function onEnableNotifications() {\n    setMessage(null);\n    setError(null);\n    try {\n      const result = await enablePushNotifications();\n      setMessage(result);\n    } catch {\n      setError("Impossible d\'activer les notifications sur cet appareil.");\n    }\n  }\n\n  function onLogout() {\n    logout();\n    navigate("/connexion");\n  }\n\n  return (\n    <div className="max-w-lg">\n      <div className="flex items-start justify-between gap-3 mb-1">\n        <h1 className="font-display text-3xl uppercase tracking-wide">Mon profil</h1>\n        <button onClick={onLogout} className="text-sm text-muted hover:text-accent transition-colors shrink-0">\n          Se déconnecter\n        </button>\n      </div>\n      <p className="text-muted text-sm mb-6">Ces infos sont juste pour toi, pas partagees avec les autres membres.</p>\n\n      <div className="flex gap-2 mb-6 md:hidden">\n        <Link\n          to="/exercices"\n          className="flex-1 text-center bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-3 py-2 text-sm"\n        >\n          📚 Exercices\n        </Link>\n        <Link\n          to="/historique"\n          className="flex-1 text-center bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-3 py-2 text-sm"\n        >\n          📈 Historique\n        </Link>\n      </div>\n\n      <Link\n        to="/coequipiers"\n        className="block mb-6 text-center bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-3 py-2 text-sm"\n      >\n        🤝 Mes coequipiers\n      </Link>\n\n      <div className="bg-surface border border-border rounded-xl p-6 mb-6 flex items-center gap-4">\n        <div className="w-20 h-20 rounded-full bg-surface2 border border-border overflow-hidden flex items-center justify-center shrink-0">\n          {user?.avatarBase64 ? (\n            <img src={user.avatarBase64} alt="" className="w-full h-full object-cover" />\n          ) : (\n            <span className="text-2xl text-muted">{user?.name?.[0]?.toUpperCase() ?? "?"}</span>\n          )}\n        </div>\n        <div>\n          <input ref={fileInputRef} type="file" accept="image/*" onChange={onAvatarChange} className="hidden" id="avatarInput" />\n          <label\n            htmlFor="avatarInput"\n            className="inline-block cursor-pointer bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-3 py-1.5 text-sm"\n          >\n            {avatarUploading ? "..." : "Changer la photo"}\n          </label>\n          {user?.avatarBase64 && (\n            <button onClick={removeAvatar} disabled={avatarUploading} className="block text-xs text-muted hover:text-accent mt-1">\n              Retirer la photo\n            </button>\n          )}\n        </div>\n      </div>\n\n      <form onSubmit={onSubmit} className="bg-surface border border-border rounded-xl p-6 space-y-4">\n        <div className="grid grid-cols-2 gap-4">\n          <div>\n            <label className="block text-sm text-muted mb-1" htmlFor="weight">\n              Poids (kg)\n            </label>\n            <input\n              id="weight"\n              type="number"\n              step="0.1"\n              min="0"\n              value={weightKg}\n              onChange={(e) => setWeightKg(e.target.value)}\n              className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n            />\n          </div>\n          <div>\n            <label className="block text-sm text-muted mb-1" htmlFor="height">\n              Taille (cm)\n            </label>\n            <input\n              id="height"\n              type="number"\n              step="0.1"\n              min="0"\n              value={heightCm}\n              onChange={(e) => setHeightCm(e.target.value)}\n              className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n            />\n          </div>\n        </div>\n\n        <div>\n          <label className="block text-sm text-muted mb-1" htmlFor="birthDate">\n            Date de naissance\n          </label>\n          <input\n            id="birthDate"\n            type="date"\n            value={birthDate}\n            onChange={(e) => setBirthDate(e.target.value)}\n            className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n          />\n        </div>\n\n        <div>\n          <label className="block text-sm text-muted mb-1" htmlFor="sex">\n            Sexe (optionnel)\n          </label>\n          <select\n            id="sex"\n            value={sex}\n            onChange={(e) => setSex(e.target.value)}\n            className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n          >\n            <option value="">Ne souhaite pas préciser</option>\n            <option value="F">Femme</option>\n            <option value="M">Homme</option>\n            <option value="AUTRE">Autre</option>\n          </select>\n        </div>\n\n        <div>\n          <label className="block text-sm text-muted mb-1" htmlFor="sport">\n            Sport / activité principale\n          </label>\n          <select\n            id="sport"\n            value={sport}\n            onChange={(e) => setSport(e.target.value)}\n            className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n          >\n            <option value="">Non précise</option>\n            {SPORTS_LIST.map((s) => (\n              <option key={s} value={s}>\n                {s}\n              </option>\n            ))}\n          </select>\n        </div>\n\n        {sport && (\n          <div>\n            <label className="block text-sm text-muted mb-1">Niveau de pratique</label>\n            <div className="flex gap-2">\n              {SPORT_LEVELS.map((lvl) => (\n                <button\n                  type="button"\n                  key={lvl.value}\n                  onClick={() => setSportLevel(lvl.value)}\n                  className={`flex-1 text-xs px-3 py-2 rounded-md border ${\n                    sportLevel === lvl.value ? "bg-accent/20 border-accent text-text" : "bg-surface2 border-border text-muted"\n                  }`}\n                >\n                  {lvl.label}\n                </button>\n              ))}\n            </div>\n          </div>\n        )}\n\n        <div>\n          <label className="block text-sm text-muted mb-1" htmlFor="location">\n            Localisation (optionnel)\n          </label>\n          <input\n            id="location"\n            value={location}\n            onChange={(e) => setLocation(e.target.value)}\n            placeholder="Ex : Angers"\n            className="w-full bg-surface2 border border-border rounded-md px-3 py-2"\n          />\n        </div>\n\n        <div>\n          <label className="block text-sm text-muted mb-2">Materiel dont je dispose</label>\n          <div className="flex flex-wrap gap-1.5">\n            {EQUIPMENT_CATALOG.map((eq) => (\n              <button\n                type="button"\n                key={eq.key}\n                onClick={() => toggleEquipment(eq.key)}\n                className={`text-xs px-2.5 py-1.5 rounded-md border ${\n                  equipment.includes(eq.key) ? "bg-accent/20 border-accent text-text" : "bg-surface2 border-border text-muted"\n                }`}\n              >\n                {eq.label}\n              </button>\n            ))}\n          </div>\n        </div>\n\n        {message && <p className="text-sm text-success">{message}</p>}\n        {error && <p className="text-sm text-accent">{error}</p>}\n\n        <button\n          type="submit"\n          disabled={busy}\n          className="bg-accent hover:bg-accentSoft transition-colors text-bg font-semibold rounded-md px-5 py-2 disabled:opacity-60"\n        >\n          {busy ? "Enregistrement..." : "Enregistrer"}\n        </button>\n      </form>\n\n      <div className="bg-surface border border-border rounded-xl p-6 mt-6">\n        <h2 className="font-display text-lg uppercase tracking-wide mb-1">Rappels</h2>\n        <p className="text-muted text-sm mb-4">\n          Active les notifications pour recevoir un rappel les jours ou une séance est prevue.\n        </p>\n        <button\n          onClick={onEnableNotifications}\n          className="bg-surface2 hover:bg-border transition-colors border border-border rounded-md px-4 py-2 text-sm"\n        >\n          Activer les notifications\n        </button>\n      </div>\n      <div className="bg-surface border border-border rounded-xl p-6 mt-6">\n        <h2 className="font-display text-lg uppercase tracking-wide mb-1">Mes camps</h2>\n        <p className="text-muted text-sm mb-4">\n          Taux de régularité global\n          {summary?.overallRegularityRate != null ? (\n            <span className="text-accent font-semibold"> · {summary.overallRegularityRate}%</span>\n          ) : (\n            <span className="italic"> · pas encore assez de recul</span>\n          )}\n        </p>\n        {summary === null && <p className="text-muted text-sm">Chargement...</p>}\n        {summary?.camps.length === 0 && <p className="text-muted text-sm italic">Aucun camp pour l\'instant.</p>}\n        <div className="space-y-2">\n          {summary?.camps.map((c) => (\n            <Link\n              key={c.id}\n              to={`/camps/${c.id}`}\n              className="block bg-surface2 hover:bg-border transition-colors border border-border rounded-md p-3"\n            >\n              <div className="flex items-center justify-between">\n                <p className="text-sm font-medium">{c.name}</p>\n                <span className="text-[10px] uppercase tracking-wide text-muted">\n                  {c.role === "COACH" ? "Entraineur" : "Coequipier"}\n                </span>\n              </div>\n              {c.description && <p className="text-xs text-muted italic mt-0.5">"{c.description}"</p>}\n              <p className="text-xs text-muted mt-1">\n                {c.memberCount} membre{c.memberCount > 1 ? "s" : ""} · {c.exercises.join(", ")}\n              </p>\n            </Link>\n          ))}\n        </div>\n      </div>\n\n      <div className="bg-surface border border-border rounded-xl p-6 mt-6">\n        <h2 className="font-display text-lg uppercase tracking-wide mb-1">Mes badges</h2>\n        <p className="text-muted text-sm mb-4">\n          Bases sur ta régularité personnelle uniquement, pas de comparaison avec les autres membres.\n        </p>\n        {badges === null && <p className="text-muted text-sm">Chargement...</p>}\n        <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">\n          {badges?.map((b) => (\n            <div\n              key={b.key}\n              title={b.description}\n              className={`rounded-lg p-3 text-center border ${\n                b.earned ? "bg-accent/10 border-accent" : "bg-surface2 border-border opacity-40"\n              }`}\n            >\n              <p className="text-2xl mb-1">{b.emoji}</p>\n              <p className="text-xs font-medium">{b.name}</p>\n            </div>\n          ))}\n        </div>\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/Teammates.tsx'] = 'import { useEffect, useState } from "react";\nimport { Link } from "react-router-dom";\nimport { api } from "../api/client";\n\ninterface UserSummary {\n  id: string;\n  name: string;\n  avatarBase64: string | null;\n  location: string | null;\n}\n\ninterface ConnectionsData {\n  accepted: { connectionId: string; user: UserSummary }[];\n  pendingSent: { connectionId: string; user: UserSummary }[];\n  pendingReceived: { connectionId: string; user: UserSummary }[];\n}\n\nexport default function Teammates() {\n  const [search, setSearch] = useState("");\n  const [results, setResults] = useState<UserSummary[]>([]);\n  const [data, setData] = useState<ConnectionsData | null>(null);\n  const [sentTo, setSentTo] = useState<string[]>([]);\n\n  function load() {\n    api.get<ConnectionsData>("/connections").then(setData);\n  }\n  useEffect(load, []);\n\n  useEffect(() => {\n    if (search.trim().length < 2) {\n      setResults([]);\n      return;\n    }\n    const timeout = setTimeout(() => {\n      api.get<UserSummary[]>(`/users/search?q=${encodeURIComponent(search.trim())}`).then(setResults);\n    }, 300);\n    return () => clearTimeout(timeout);\n  }, [search]);\n\n  async function sendRequest(userId: string) {\n    await api.post("/connections", { recipientId: userId });\n    setSentTo((prev) => [...prev, userId]);\n  }\n\n  async function accept(connectionId: string) {\n    await api.post(`/connections/${connectionId}/accept`, {});\n    load();\n  }\n\n  async function remove(connectionId: string) {\n    await api.del(`/connections/${connectionId}`);\n    load();\n  }\n\n  const allKnownIds = new Set([\n    ...(data?.accepted.map((c) => c.user.id) ?? []),\n    ...(data?.pendingSent.map((c) => c.user.id) ?? []),\n    ...(data?.pendingReceived.map((c) => c.user.id) ?? []),\n  ]);\n\n  return (\n    <div className="max-w-lg">\n      <h1 className="font-display text-3xl uppercase tracking-wide mb-1">Coequipiers</h1>\n      <p className="text-muted text-sm mb-6">\n        Recherche une personne par son nom pour lui proposer de devenir coequipier et acceder a son profil.\n      </p>\n\n      <input\n        value={search}\n        onChange={(e) => setSearch(e.target.value)}\n        placeholder="Rechercher par nom..."\n        className="w-full bg-surface2 border border-border rounded-md px-3 py-2 mb-3"\n      />\n\n      {results.length > 0 && (\n        <div className="space-y-2 mb-6">\n          {results.map((u) => (\n            <div key={u.id} className="flex items-center justify-between bg-surface border border-border rounded-md p-3">\n              <div className="flex items-center gap-2">\n                <div className="w-8 h-8 rounded-full bg-surface2 border border-border overflow-hidden flex items-center justify-center shrink-0">\n                  {u.avatarBase64 ? (\n                    <img src={u.avatarBase64} alt="" className="w-full h-full object-cover" />\n                  ) : (\n                    <span className="text-xs text-muted">{u.name[0]?.toUpperCase()}</span>\n                  )}\n                </div>\n                <div>\n                  <p className="text-sm">{u.name}</p>\n                  {u.location && <p className="text-xs text-muted">{u.location}</p>}\n                </div>\n              </div>\n              {allKnownIds.has(u.id) || sentTo.includes(u.id) ? (\n                <span className="text-xs text-muted">Demande envoyee</span>\n              ) : (\n                <button\n                  onClick={() => sendRequest(u.id)}\n                  className="text-xs bg-accent text-bg font-semibold rounded-md px-3 py-1.5"\n                >\n                  + Ajouter\n                </button>\n              )}\n            </div>\n          ))}\n        </div>\n      )}\n\n      {data && data.pendingReceived.length > 0 && (\n        <div className="mb-6">\n          <h2 className="font-display uppercase tracking-wide text-sm mb-2">Demandes recues</h2>\n          <div className="space-y-2">\n            {data.pendingReceived.map((c) => (\n              <div key={c.connectionId} className="flex items-center justify-between bg-surface border border-border rounded-md p-3">\n                <p className="text-sm">{c.user.name}</p>\n                <div className="flex gap-2">\n                  <button onClick={() => accept(c.connectionId)} className="text-xs bg-accent text-bg font-semibold rounded-md px-3 py-1.5">\n                    Accepter\n                  </button>\n                  <button onClick={() => remove(c.connectionId)} className="text-xs text-muted hover:text-accent">\n                    Refuser\n                  </button>\n                </div>\n              </div>\n            ))}\n          </div>\n        </div>\n      )}\n\n      <h2 className="font-display uppercase tracking-wide text-sm mb-2">Mes coequipiers</h2>\n      {data === null && <p className="text-muted text-sm">Chargement...</p>}\n      {data?.accepted.length === 0 && <p className="text-muted text-sm italic">Aucun coequipier pour l\'instant.</p>}\n      <div className="space-y-2">\n        {data?.accepted.map((c) => (\n          <Link\n            key={c.connectionId}\n            to={`/profil/${c.user.id}`}\n            className="flex items-center justify-between bg-surface hover:bg-surface2 transition-colors border border-border rounded-md p-3"\n          >\n            <div className="flex items-center gap-2">\n              <div className="w-8 h-8 rounded-full bg-surface2 border border-border overflow-hidden flex items-center justify-center shrink-0">\n                {c.user.avatarBase64 ? (\n                  <img src={c.user.avatarBase64} alt="" className="w-full h-full object-cover" />\n                ) : (\n                  <span className="text-xs text-muted">{c.user.name[0]?.toUpperCase()}</span>\n                )}\n              </div>\n              <p className="text-sm">{c.user.name}</p>\n            </div>\n            <span className="text-xs text-accent">Voir le profil →</span>\n          </Link>\n        ))}\n      </div>\n\n      {data && data.pendingSent.length > 0 && (\n        <div className="mt-6">\n          <h2 className="font-display uppercase tracking-wide text-sm mb-2">Demandes envoyees (en attente)</h2>\n          <div className="space-y-2">\n            {data.pendingSent.map((c) => (\n              <div key={c.connectionId} className="flex items-center justify-between bg-surface border border-border rounded-md p-3">\n                <p className="text-sm text-muted">{c.user.name}</p>\n                <button onClick={() => remove(c.connectionId)} className="text-xs text-muted hover:text-accent">\n                  Annuler\n                </button>\n              </div>\n            ))}\n          </div>\n        </div>\n      )}\n    </div>\n  );\n}\n'
FILES['frontend/src/pages/PublicProfile.tsx'] = 'import { useEffect, useState } from "react";\nimport { Link, useParams } from "react-router-dom";\nimport { api } from "../api/client";\n\ninterface PublicProfileData {\n  id: string;\n  name: string;\n  avatarBase64: string | null;\n  location: string | null;\n  sport: string | null;\n  sportLevel: string | null;\n  overallRegularityRate: number | null;\n  badgeCount: number;\n  camps: { id: string; name: string; description: string | null; memberCount: number }[];\n}\n\nexport default function PublicProfile() {\n  const { userId } = useParams<{ userId: string }>();\n  const [profile, setProfile] = useState<PublicProfileData | null>(null);\n  const [error, setError] = useState<string | null>(null);\n\n  useEffect(() => {\n    if (!userId) return;\n    api\n      .get<PublicProfileData>(`/connections/${userId}/profile`)\n      .then(setProfile)\n      .catch(() => setError("Vous devez etre coequipiers ou partager un camp pour voir ce profil."));\n  }, [userId]);\n\n  if (error) {\n    return (\n      <div className="max-w-lg">\n        <p className="text-accent text-sm">{error}</p>\n        <Link to="/coequipiers" className="text-accent hover:text-accentSoft text-sm">\n          ← Retour\n        </Link>\n      </div>\n    );\n  }\n\n  if (!profile) return <p className="text-muted">Chargement...</p>;\n\n  return (\n    <div className="max-w-lg">\n      <Link to="/coequipiers" className="text-sm text-muted hover:text-accent">\n        ← Retour aux coequipiers\n      </Link>\n\n      <div className="flex items-center gap-4 mt-3 mb-6">\n        <div className="w-20 h-20 rounded-full bg-surface2 border border-border overflow-hidden flex items-center justify-center shrink-0">\n          {profile.avatarBase64 ? (\n            <img src={profile.avatarBase64} alt="" className="w-full h-full object-cover" />\n          ) : (\n            <span className="text-2xl text-muted">{profile.name[0]?.toUpperCase()}</span>\n          )}\n        </div>\n        <div>\n          <h1 className="font-display text-2xl uppercase tracking-wide">{profile.name}</h1>\n          {profile.location && <p className="text-muted text-sm">📍 {profile.location}</p>}\n          {profile.sport && (\n            <p className="text-muted text-sm">\n              {profile.sport} {profile.sportLevel === "COMPETITION" ? "(competition)" : "(loisir)"}\n            </p>\n          )}\n        </div>\n      </div>\n\n      <div className="grid grid-cols-2 gap-3 mb-6">\n        <div className="bg-surface border border-border rounded-xl p-4 text-center">\n          <p className="font-display text-2xl text-accent">\n            {profile.overallRegularityRate != null ? `${profile.overallRegularityRate}%` : "—"}\n          </p>\n          <p className="text-[10px] text-muted uppercase tracking-wide mt-1">Regularite globale</p>\n        </div>\n        <div className="bg-surface border border-border rounded-xl p-4 text-center">\n          <p className="font-display text-2xl text-accent">{profile.badgeCount}</p>\n          <p className="text-[10px] text-muted uppercase tracking-wide mt-1">Badges obtenus</p>\n        </div>\n      </div>\n\n      <h2 className="font-display uppercase tracking-wide text-sm mb-2">Camps</h2>\n      <div className="space-y-2">\n        {profile.camps.map((c) => (\n          <div key={c.id} className="bg-surface border border-border rounded-md p-3">\n            <p className="text-sm font-medium">{c.name}</p>\n            {c.description && <p className="text-xs text-muted italic mt-0.5">"{c.description}"</p>}\n            <p className="text-xs text-muted mt-1">{c.memberCount} membre{c.memberCount > 1 ? "s" : ""}</p>\n          </div>\n        ))}\n        {profile.camps.length === 0 && <p className="text-muted text-sm italic">Aucun camp.</p>}\n      </div>\n    </div>\n  );\n}\n'
FILES['frontend/src/App.tsx'] = 'import { Navigate, Route, Routes } from "react-router-dom";\nimport { ReactNode } from "react";\nimport { useAuth } from "./context/AuthContext";\nimport Layout from "./components/Layout";\n\nimport Login from "./pages/Login";\nimport Register from "./pages/Register";\nimport Profile from "./pages/Profile";\nimport Dashboard from "./pages/Dashboard";\nimport CreateCamp from "./pages/CreateCamp";\nimport JoinCamp from "./pages/JoinCamp";\nimport CampDetail from "./pages/CampDetail";\nimport Today from "./pages/Today";\nimport Progress from "./pages/Progress";\nimport ExerciseRepository from "./pages/ExerciseRepository";\nimport CampChat from "./pages/CampChat";\nimport Messages from "./pages/Messages";\nimport CampLeaderboard from "./pages/CampLeaderboard";\nimport Chrono from "./pages/Chrono";\nimport ActivityHistory from "./pages/ActivityHistory";\nimport CampCalendar from "./pages/CampCalendar";\nimport ForgotPassword from "./pages/ForgotPassword";\nimport ResetPassword from "./pages/ResetPassword";\nimport Teammates from "./pages/Teammates";\nimport PublicProfile from "./pages/PublicProfile";\n\nfunction Private({ children }: { children: ReactNode }) {\n  const { user, loading } = useAuth();\n  if (loading) return <div className="min-h-screen flex items-center justify-center text-muted">Chargement...</div>;\n  if (!user) return <Navigate to="/connexion" replace />;\n  return <Layout>{children}</Layout>;\n}\n\nexport default function App() {\n  return (\n    <Routes>\n      <Route path="/connexion" element={<Login />} />\n      <Route path="/inscription" element={<Register />} />\n      <Route path="/mot-de-passe-oublie" element={<ForgotPassword />} />\n      <Route path="/reinitialiser-mot-de-passe" element={<ResetPassword />} />\n\n      <Route path="/aujourdhui" element={<Private><Today /></Private>} />\n      <Route path="/profil" element={<Private><Profile /></Private>} />\n      <Route path="/camps" element={<Private><Dashboard /></Private>} />\n      <Route path="/camps/creer" element={<Private><CreateCamp /></Private>} />\n      <Route path="/camps/rejoindre" element={<Private><JoinCamp /></Private>} />\n      <Route path="/camps/:id" element={<Private><CampDetail /></Private>} />\n      <Route path="/camps/:id/progression/:exerciseId" element={<Private><Progress /></Private>} />\n      <Route path="/camps/:id/calendrier" element={<Private><CampCalendar /></Private>} />\n      <Route path="/exercices" element={<Private><ExerciseRepository /></Private>} />\n      <Route path="/camps/:id/discussion" element={<Private><CampChat /></Private>} />\n      <Route path="/camps/:id/classement" element={<Private><CampLeaderboard /></Private>} />\n      <Route path="/chrono" element={<Private><Chrono /></Private>} />\n      <Route path="/historique" element={<Private><ActivityHistory /></Private>} />\n      <Route path="/messages" element={<Private><Messages /></Private>} />\n      <Route path="/coequipiers" element={<Private><Teammates /></Private>} />\n      <Route path="/profil/:userId" element={<Private><PublicProfile /></Private>} />\n\n      <Route path="*" element={<Navigate to="/aujourdhui" replace />} />\n    </Routes>\n  );\n}\n'
FILES['frontend/src/components/Layout.tsx'] = 'import { NavLink, useNavigate } from "react-router-dom";\nimport { ReactNode } from "react";\nimport { useAuth } from "../context/AuthContext";\n\nconst desktopNavItems = [\n  { to: "/aujourdhui", label: "Aujourd\'hui" },\n  { to: "/camps", label: "Mes camps" },\n  { to: "/chrono", label: "Chrono" },\n  { to: "/exercices", label: "Exercices" },\n  { to: "/messages", label: "Messages" },\n  { to: "/coequipiers", label: "Coequipiers" },\n  { to: "/historique", label: "Historique" },\n  { to: "/profil", label: "Profil" },\n];\n\n// Sur mobile, la barre du bas ne montre que l\'essentiel : le Chrono a sa propre bulle\n// centrale, les autres onglets (Exercices, Historique) restent accessibles depuis le menu\n// complet sur ordinateur, ou via des liens dans "Mes camps" / "Profil" sur mobile.\nconst mobileLeftItems = [\n  { to: "/aujourdhui", label: "Aujourd\'hui", icon: "📅" },\n  { to: "/camps", label: "Camps", icon: "🏕️" },\n];\nconst mobileRightItems = [\n  { to: "/messages", label: "Messages", icon: "💬" },\n  { to: "/profil", label: "Profil", icon: "👤" },\n];\n\nexport default function Layout({ children }: { children: ReactNode }) {\n  const { user, logout } = useAuth();\n  const navigate = useNavigate();\n\n  return (\n    <div className="min-h-screen flex flex-col md:flex-row">\n      <header className="md:w-64 md:min-h-screen border-b md:border-b-0 md:border-r border-border bg-surface flex md:flex-col justify-between">\n        <div className="p-4 md:p-6 w-full">\n          <div className="flex items-center justify-center md:justify-start gap-2 mb-0 md:mb-8">\n            <img src="/logo-mark.png" alt="" className="w-11 h-11 md:w-8 md:h-8 object-contain" />\n            <span className="font-display text-xl md:text-lg tracking-wide uppercase">GoTeam</span>\n          </div>\n          <nav className="hidden md:flex md:flex-col gap-1">\n            {desktopNavItems.map((item) => (\n              <NavLink\n                key={item.to}\n                to={item.to}\n                className={({ isActive }) =>\n                  `px-3 py-2 rounded-md text-sm font-medium transition-colors ${\n                    isActive ? "bg-accent/15 text-accent" : "text-muted hover:text-text hover:bg-surface2"\n                  }`\n                }\n              >\n                {item.label}\n              </NavLink>\n            ))}\n          </nav>\n        </div>\n        <div className="p-6 hidden md:block">\n          {user && <p className="text-xs text-muted mb-2 truncate">{user.name}</p>}\n          <button\n            onClick={() => {\n              logout();\n              navigate("/connexion");\n            }}\n            className="text-sm text-muted hover:text-accent transition-colors"\n          >\n            Se déconnecter\n          </button>\n        </div>\n      </header>\n\n      <main className="flex-1 p-5 pb-24 md:p-10 md:pb-10 max-w-4xl mx-auto w-full order-1">{children}</main>\n\n      {/* Barre de navigation mobile, fixee en bas, avec le Chrono en bulle centrale */}\n      <nav className="md:hidden fixed bottom-0 inset-x-0 bg-surface border-t border-border flex items-end justify-around pb-1 pt-2 z-40">\n        {mobileLeftItems.map((item) => (\n          <NavLink\n            key={item.to}\n            to={item.to}\n            className={({ isActive }) =>\n              `flex-1 flex flex-col items-center gap-0.5 py-1 text-[10px] font-medium ${\n                isActive ? "text-accent" : "text-muted"\n              }`\n            }\n          >\n            <span className="text-lg leading-none">{item.icon}</span>\n            {item.label}\n          </NavLink>\n        ))}\n\n        <NavLink to="/chrono" className="flex-1 flex flex-col items-center -mt-7">\n          {({ isActive }) => (\n            <>\n              <span\n                className={`w-14 h-14 rounded-full flex items-center justify-center text-2xl shadow-lg border-4 border-bg ${\n                  isActive ? "bg-accentSoft" : "bg-accent"\n                } text-bg`}\n              >\n                ⏱\n              </span>\n              <span className={`text-[10px] font-medium mt-0.5 ${isActive ? "text-accent" : "text-muted"}`}>\n                Chrono\n              </span>\n            </>\n          )}\n        </NavLink>\n\n        {mobileRightItems.map((item) => (\n          <NavLink\n            key={item.to}\n            to={item.to}\n            className={({ isActive }) =>\n              `flex-1 flex flex-col items-center gap-0.5 py-1 text-[10px] font-medium ${\n                isActive ? "text-accent" : "text-muted"\n              }`\n            }\n          >\n            <span className="text-lg leading-none">{item.icon}</span>\n            {item.label}\n          </NavLink>\n        ))}\n      </nav>\n    </div>\n  );\n}\n'

for rel_path, content in FILES.items():
    p = pathlib.Path(rel_path)
    p.parent.mkdir(parents=True, exist_ok=True)
    p.write_text(content, encoding='utf-8')
    print('OK ->', rel_path)

